window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_048"]={"n":"庄昶","dyn":"明","poems":[{"t":"题竹","f":"五言古诗","c":["独坐湘江浔，见此丛篁幽。","风雨日暝晦，万雀声啁啾。","垂垂正结实，恐为鹓雏谋。","岂无九苞羽，飞下十二楼。","延伫久不见，此意良悠悠。","我因王者瑞，极意垂鸿猷。","采之欲往食，道路阻且修。","问之在何所，乃古西康州。","西康有西伯，已矣三千秋。","至尊应昌运，致此能无忧。","清时一再睹，咄哉何所求。"]},{"t":"养庵为永兴马贞夫元题","f":"五言古诗","c":["北岳霜雪干，玉汉强千寻。","南溟珊瑚枝，玄宫极幽深。","应谁见毫末，积效踰山岑。","抚卷得玩颐，隐几亦观心。","辞琢岂金玉，受厉须黄金。","无寐月自生，无觉日自沉。","回首人间世，坐骛复行吟。","枵然舍予琴，谁哉赏此音。"]},{"t":"苍松为许志完作","f":"七言古诗","c":["箕山老人松树图，开卷凌乱千人呼。","毕宏已老更谁手，南京老盛天下无。","此松画本得何处，元是公家挂瓢树。","虬髯偃蹇老铁蟠，雷雨苍龙未腾去。","呜呼此树百鍊钢，数千万变冰与霜。","忠臣义士我所拜，山中万古文天祥。"]},{"t":"游琅琊寺 其二","f":"七言律诗","c":["偶上蓬莱第一重，道人今夜宿芙蓉。","尘埋下界三千丈，月在西岩七十峰。","江海几年留老眼，乾坤今日寄微踪。","酒醒无限题诗意，起立层岩看万松。"]},{"t":"寿柳处士用美宣地官韵","f":"七言律诗","c":["年华不敢去堂堂，老恋山光及水光。","尘梦几看浮世短，白云交付此杯长。","柳根怪石方床枕，眼底秋灯细字行。","小阮年年无限意，长江分遣到壶觞。"]},{"t":"吊易羽士姜守一 其一","f":"七言律诗","c":["一鹤西来瘦有馀，每将生死问何如。","几回见我扶还拜，两月来书病不除。","枕上希夷千古梦，手中庄子十年书。","人间若果神仙有，愿候新江旧草庐。"]},{"t":"用韵寄黄提学","f":"七言律诗","c":["秋老青山色更浓，年年此地问元龙。","狂搔短发孤鸿外，病卧高楼细雨中。","诗寄故人如见面，年过五十敢称翁。","何时许作西岩会，一日一壶倾一峰。"]},{"t":"济宁舟中 其二","f":"七言律诗","c":["不管青天问去鸿，百年都只此杯中。","千家小聚村村暝，万里河流岸岸同。","远树入河留返照，布帆随力饱西风。","南来北往奔波地，留与儿童笑老翁。"]},{"t":"东昌舟中 其一","f":"七言律诗","c":["万里江湖数起居，乾坤历历过青徐。","得风水远孤帆外，牵月河长百丈馀。","俗债可容还醉笔，老魔犹与战残书。","可知酒兴今多少，自点秋滩问买鱼。"]},{"t":"舟中 其一","f":"七言律诗","c":["暮霭千家望欲平，风光著处有诗情。","秋灯小榻留孤艇，疏雨寒城打二更。","石自隔河分别界，人将望驿问何程。","同行我亦朝天客，两鬓羞看雪乱明。"]},{"t":"直沽 其二","f":"七言律诗","c":["匆匆光景到香醪，万里天涯两鬓毛。","北海风回帆腹饱，长河霜冷岸痕高。","寒城敛雾山俱出，老句横秋气亦豪。","拱北楼高沧海近，夕阳阑槛倚秋涛。"]},{"t":"石翁见寄次韵 其二","f":"七言律诗","c":["万里长风击楫歌，了无此梦挂烟萝。","溪山到脚长嫌少，车马临门不爱多。","瓢挂树稍风淅历，鹤巢松盖梦蹉跎。","一声引起渔家傲，两两三三唱隔波。"]},{"t":"书东山草堂扁 其一","f":"七言律诗","c":["封题云卧东山扁，歌咏司空表圣诗。","天阙星辰遗旧履，橘洲岁月有残棋。","石横流潦潜虬角，梅迸垂萝屈铁枝。","自笑野人閒袖手，云烟浓淡忽交驰。"]},{"t":"书东山草堂扁 其二","f":"七言律诗","c":["黄落空山满地知，江湖残线一襟诗。","是天荣瘁元无意，犯手输赢不会棋。","沙苑草非骐骥秣，潇湘竹是凤凰枝。","紫虚有约千回醉，笑指僧趺亦坐驰。"]},{"t":"五羊寄邓先生俊 其二","f":"七言律诗","c":["后时自许甘丘壑，前席将无问鬼神。","浮世虚名非得已，出山小草却悲人。","别时笑语风吹断，会处迷离梦写真。","四十馀年一回首，乾旋坤转有冬春。"]},{"t":"木昌道中 其二","f":"七言律诗","c":["远去江湖志不违，今来未觉昔来非。","眼穿海月笼沙白，足倚熏笼贮火微。","行客自知无岁暮，飞鸿不记有家归。","脚跟自有平生路，未许缁尘点素衣。"]},{"t":"叠前韵 其三","f":"七言律诗","c":["又向清湘弄一舟，笑将双脚问清流。","囊收风月非穷相，梦熟烟霞最上头。","招隐谁甘同寂寞，著书独不为穷愁。","稻粱满地悲鸿旧，驯得沧波万里鸥。"]},{"t":"叠前韵 其四","f":"七言律诗","c":["荡荡白虹扬一舟，乾坤孤影在中流。","风高物外浮溟兴，天盖人间岸帻头。","历坂盐车骐骥病，委霜人路菊花愁。","也知万户封侯乐，一点真閒不及鸥。"]},{"t":"答李西涯","f":"七言律诗","c":["十年风雨别长安，笑把无穷作梦看。","纵许浮云终日定，谁知去缚此心难。","蘋花采采江空远，湘水茫茫道路艰。","读罢《离骚》风偶急，钓船吹上子陵滩。"]},{"t":"沈公见寄次韵奉答 其一","f":"七言律诗","c":["婆娑独对皇天影，谈笑都来俗子喧。","芥子须弥还我闼，千红万紫亦春园。","心无牛口干秦穆，迹继龙头愧邴原。","江上神龟尾方曳，放情泥淖不须掀。"]},{"t":"谢天与改官汴臬幕东峤兄有诗次韵并寄 其一","f":"七言律诗","c":["梁国何曾还哧我，今人情或古人同。","电悬双眼欺秋水，髻拥三花御野风。","柱史官来头已白，醉乡逃去颊初红。","吹台独上高回首，各各溪河落照中。"]},{"t":"郊行","f":"七言绝句","c":["凌兢瘦马踏春泥，雪后郊原绿未齐。","一抹午烟风隔断，野鸡声在竹林西。"]},{"t":"钓鱼图 其三","f":"七言绝句","c":["溪上春云与浪飞，溪头春水鲚鱼肥。","野人只是閒无事，日出船来月出归。"]},{"t":"端午食赐粽有感","f":"七言古诗","c":["蓬莱宫中悬艾虎，舟满龙池竞箫鼓。","千官晓缀紫宸班，拜向彤墀贺重午。","大官角黍菰蒲香，彩绳万缕云霞光。","天恩敕赐下丹陛，琼筵侑以黄金觞。","东南米价高如玉，江淮饿莩千家哭。","官河戍卒十万艘，总向天厨挽飞粟。","君门大嚼心岂安，谁能持此回凋残。","小臣自愧悠悠者，救时无术真素餐。"]},{"t":"节妇","f":"七言律诗","c":["二十夫君弃妾身，诸郎痴小舅姑贫。","自甘薄命同衰叶，不扫蛾眉嫁别人。","化石未成犹有泪，舞鸾虽在不惊尘。","琐窗独向东风树，岁岁花开他自春。"]},{"t":"张秋 其二","f":"七言绝句","c":["经国能终瓠子甘，转漕万里只东南。","屯田果得京师计，请为朝廷拜邵庵。"]},{"t":"张秋 其三","f":"七言绝句","c":["本觉神龙欲可嗟，人间水性岂容加。","往年记得徐夫子，用尽山东铁万家。"]},{"t":"送南海范规","f":"七言律诗","c":["每见江门说范云，花山日日绕吟魂。","小童忽报来何客，野鹤昂然立我门。","口中公甫诗无数，手里芙蓉杖一根。","一语未终还别去，月明人自白沙村。"]},{"t":"柳塘春意","f":"五言律诗","c":["万物吾一身，著眼无不是。","大程方少年，曾点亦狂士。","真乐本忘言，一笑乃深契。","还知万柳中，春塘雨方霁。"]},{"t":"梅花卷","f":"五言律诗","c":["老矣孤山中，那复他料理。","惟兹太极心，点缀寒梅几。","暗香疏影诗，戏剧乃如此。","安得无极翁，共此无极旨。"]},{"t":"江湖胜览卷","f":"五言古诗","c":["沧溟水一沤，天地一芥子。","我问具眼人，此眼何处使。","从今打扑破，此眼吾眼耳。"]},{"t":"雪梅","f":"五言古诗","c":["太极图偶封，天地若混沌。","不知滕六谁，乃打无极诨。","安得邵尧夫，閒与一究竟。"]},{"t":"送白沙先生门人容彦昭陈秉常回南海次韵","f":"五言律诗","c":["君子久不见，一书凡几月。","开门见高徒，仪形宛相接。","可久亦可大，自抱贤人业。","束书不可羁，含情送归楫。"]},{"t":"橘潭和杜韵","f":"五言古诗","c":["撄宁何处所，天地此溪堂。","世物如凋瘵，医门有栋梁。","寒泉真自冽，老橘故须香。","水晚留苍翠，花深到淼茫。","净回真本色，定有碧圆光。","实好垂垂大，根灵故故长。","绿非悬宿雨，黄岂弄秋霜。","沆瀣仙浆里，方书圣道傍。","野夫长老病，白首几低昂。","多谢扶持力，残生岂敢忘。"]},{"t":"沃洲山为新昌石秉殷赋","f":"五言古诗","c":["我闻沃洲山，渺绝如仙洲。","仙洲不可到，梦想空自遒。","清风为我御，白云为我辀。","欲凭万古心，穷此天地幽。","何时沃洲仙，与我相绸缪。","振衣鳌峰冈，濯足津溪流。","把画庖牺图，开卷大禹畴。","六经不得志，万古重删修。","悠悠天壤间，邈矣吾何求。"]},{"t":"题蒙泉葡萄卷","f":"七言古诗","c":["古今万妙真无穷，飞走动植皆化工。","葡萄杨柳几千卉，尧夫老眼观物中。","蒙泉学士燕山杰，平生邵学王天悦。","白头一睹甘州英，老痒欲搔搔未得。","濡毫大叫扫不停，墨花一放三千城。","须臾万纸各飞动，累累总是皇极精。","相马无将九方处，不向骊黄论形似。","要知花柳过前川，閒弄程家真意思。"]},{"t":"和石翁赠郑通政云山吟","f":"古风","c":["云苍苍，水悠悠，青山万古人白头。","华山老母一渴睡，天地枕席今未收。","尘缨自濯已堪喜，敝屣既脱何足留。","河图凤鸟至不至，仲尼已没无人愁。","嗟乎仲尼已没无人愁，乾坤谁解生民忧。","羲文尧禹正今日，千年治道还西周。"]},{"t":"与竹泉道士","f":"古风","c":["燕城道士冯竹泉，定山风雨来相过。","向人两眼如两星，头上笠子五尺大。","开门握手延入坐，须家诗书携一个。","自言仙道亦颇佳，老死人间已除破。","古今词翰岂易得，吾子高名吾所慕。","卢老神丹我解传，老杜长篇子须作。","呜呼道士吾与汝，黑发红颜何用那。","痛惟老父双膝拳，日夜高床五年卧。","仓公俞附竟何人，仰首苍天泪交堕。","刀圭相乞倘不辞，呕出吾心吾亦可。","道士道士，何须再拜苦索我。"]},{"t":"雪蓬为盛行之作","f":"七言古诗","c":["雪蓬老人瘦且清，前身想只梅花精。","墨梅一写几千万，鸡林交趾知其名。","南京小儿不晓事，相逢尽唤梅先生。","一蓬有屋凤城里，土脊茅檐竹椽子。","蜗牛半角祗藏头，我为量之刚丈许。","不题偃月昼锦堂，扁作雪蓬聊尔耳。","北风大雪五尺深，无限傍人愁压死。","老人高坐方掀髯，大叫狂歌对儿女。","大儿捧笔妇捧觞，一醉梅花三百纸。","篱边竹树往往佳，万个弓弰千鼠尾。","忽然几处鼎石根，便是悬崖活梅树。","此时天趣不可当，谁人肯许同清狂。","花光补之己非敌，当时空有王元章。","定山先生无一好，雪蓬老人当笑倒。","只有区区观物亭，半庭茂叔窗前草。"]},{"t":"定山歌用杜韵","f":"七言律诗","c":["定山不与灵山白，万古江淮一峰碧。","青天作盖拥层巅，北斗当空挂岩石。","我今借此一榻云，欲与希夷华山敌。","豪来得句不肯眠，醉笔一挥千丈壁。"]},{"t":"定山泉歌和杜韵","f":"七言律诗","c":["此泉门外不可断，日日来过如相依。","小扶藜杖看清浊，老人雨后锄园归。","游人一见讵敢唾，白鹭偶来何忍飞。","耳聋眼暗与世恶，此泉磊落人间稀。"]},{"t":"木石图为许志完作","f":"七言古诗","c":["定山破袖无尺大，东归袖取蓬莱峰。","峰头老秃几千树，槎牙万古撑长空。","箕山老人不晓事，问余欲向青天住。","醉中见许不作难，袖中滚滚倾天地。","老人睹此造化权，返却而走心茫然。","忽然江海一平地，千仞万仞飞苍烟。","锦树苍峰不须买，草阁秋崖明月在。","白头得此当有知，还我东坡袖中海。"]},{"t":"和司马提学倡和诗韵 来教和王尚文司谏见怀之作奉和一章兼呈司谏 其一","f":"七言古诗","c":["江山契合胶漆凝，君子小人炭与冰。","两公投分忽京国，一洗世间桃李色。","同心契合真断金，老眼乾坤谁并得。","一公海月照木难，一公天马辞尘鞍。","青天英爽总高兴，白日坐收千古暝。","与人同善真我思，古今四海皆相知。"]},{"t":"和司马提学倡和诗韵 来教谓尚文再和只有梅花知之句甚动野夫寻梅之兴复和一章昶亦奉和请教 其二","f":"七言古诗","c":["冻云四划天地凝，一口嚼碎万里冰。","借天欲赏梅花国，天许先生无吝色。","白头中坐太极圈，醉点万花归未得。","天心子半知者难，一枝笑撚随归鞍。","乾坤万古有真兴，梦中说梦空痴暝。","定山老我徒尔思，此乐惟许先生知。"]},{"t":"和司马提学倡和诗韵 来教谓寻梅之约已订然不知此中梅易得否李贞伯和章虽有相寻不难之句然亦约莫之言耳故更和一章问尚文土人云昶为贞伯解围遂亦不揣和奉一章然亦不知更为约莫之言否也 其三","f":"七言古诗","c":["江山雪冷冻欲凝，梅花万壑藏深冰。","数枝何处更江国，淡影无香亦无色。","看花须看花未开，公欲寻梅寻便得。","徒然约莫寻本难，白头烂醉空吟鞍。","李君平生亦清兴，未始归途日空暝。","公才自出人所思，那得李君真不知。"]},{"t":"和司马提学倡和诗韵 来教谓从者云此地故少梅追念旧乐怅然兴怀复和一章昶亦奉和一章以答从者 其四","f":"七言古诗","c":["人间一理万物凝，夏虫底用多疑冰。","我曾烂赏万花国，每谓乾坤总形色。","梅花肯欲为公寻，江北江南皆可得。","指灯为火谅不难，不然枉跨城东鞍。","万紫千红总佳兴，影响前头路空暝。","高斋独坐几深思，此意我知公亦知。"]},{"t":"和司马提学倡和诗韵 来教谓尚文寻梅诗比类精绝思致深远但微近相亵不可为训更和一章为老梅写怀请教亦不知老梅之怀果如此否也 其五","f":"七言古诗","c":["草窗万物生意凝，梅花岂惮霜与冰。","平生不解作倾国，古淡只随真本色。","春风自许先群芳，岂是群芳同未得。","古今何许真赏难，风花荡满青骢鞍。","万紫千红总佳兴，老眼梅花肯孤暝。","乾坤此意君且思，物各付物谁大知。"]},{"t":"和司马提学倡和诗韵 来教谓陈师召太常久稽和章以此见促昶亦以太常非久稽者以全取胜故耳故揣太常之意亦奉和一章 其六","f":"七言古诗","c":["诗坛四野冻云凝，重兵十万屯坚冰。","梅花相遇几敌国，战酣落日天无色。","相持不胜不肯休，不是老梅禁不得。","太常先生岂和难，手持巨槊横吟鞍。","养威自待有馀兴，一鼓坐收天地暝。","诗家老将须更思，仁者无敌何人知。"]},{"t":"和司马提学倡和诗韵 来教谓寻梅告劳且将移梅一章昶以移梅寻梅难易何如亦以一章奉和 其七","f":"七言古诗","c":["折胶万里争严凝，瘦筇拄断江南冰。","寻梅约到罗浮国，瘦马疲童总难色。","先生乃谓寻颇劳，岂若移梅两相得。","移梅恐比寻更难，天机吹到春风鞍。","风光聊遣适吾兴，肯被梅花恼春暝。","有无难易何足思，乾坤礼乐先生知。"]},{"t":"和司马提学倡和诗韵 承不鄙见赐诸作命和登卷敢逐一依韵请教不胜愧感更和一章 其八","f":"七言古诗","c":["深山破屋苔已凝，敲门忽枉清玉冰。","问之何来自京国，清诗润澈珊瑚色。","梅花句句太极图，合是濂溪乃吟得。","老夫奉和不敢难，诗肩出耸驴背鞍。","短才无学更无兴，信口风花醉初暝。","无他意义公莫思，野老山歌吾自知。"]},{"t":"和惧庵先生定山石","f":"七言古诗","c":["乾坤何物非鸿造，奇妙极为千古好。","惧庵天挺观物豪，老脚溪山无不造。","定山此石绝奇古，地秘天藏得深奥。","万形吐露总天机，呈怪争雄各轩闹。","回身菌缩龙屈蟠，仰首狞狰虎蹲啸。","鸿濛自判各付与，高者巉空下深潦。","流形彼此固已安，谁复欢忻与悲悼。","世人剑首吹吷然，浑沌那知有真窍。","惧庵览此万丈奇，抚掌阴阳叫真妙。","笑拈水火土一挥，天地精灵愈辉耀。","雨风雷露交相形，日月星辰炫高照。","庖羲画里春熙熙，皇极眼中天浩浩。","纵观万古我何人，也一掀髯与公笑。"]},{"t":"题通伯先生山水画","f":"七言古诗","c":["乾坤万物吾一体，此意人间几山水。","平生画者知未知，一幅烟云春万里。","苍然蔚然神莫涯，动者植者妙何拟。","平溪欲静苍天留，白云忽散青山起。","世人看尽只是画，眼底谁能会斯理。","惧庵天挺观物豪，天地斯人能有几。","鸢飞鱼跃忽满前，正契吾心妙斯旨。","三十六宫遍挂之，一日一宫春煦煦。","明月天心舞邵雍，春草庭前梦周子。","先生不鄙痴老翁，持向定山拈一语。","老翁高坐溪云亭，春在千岩正红紫。","笑将此画聊捲之，更与先生看真此。"]},{"t":"泉山为新安吴以魁作","f":"楚辞体","c":["结吾庐兮山麓，濯吾足兮泉央。","邈斯人兮何为，随吾道兮行藏。","知圣人兮在上，慕洗耳兮虞唐。","泉有鱼兮活活，山有木兮苍苍。","慨箕颍兮不见，聊自适兮徜徉。","如有我兮梦卜，胡斯世兮敢忘。"]},{"t":"松石歌为周礼作","f":"七言古诗","c":["老翁梦携东海来，袖中犹带鸿濛胎。","天蓬亭下一点缀，歘然散作三蓬莱。","中峰耸拔极天巧，旁有三峰更奇峭。","苏家父子俱下风，勾曲三茅犹老草。","层峦起伏意不穷，更从奇处著两松。","云烟几笔天几峰，天然李白金芙蓉。","老翁此手无他妙，能将松石供谈笑。","王维马远绝古今，老笔虽工犹未到。","老翁老翁须天生，前身只是松石精。","呵呵一醉白云里，笑将松石呼翁名。","老翁谓我假松石，但呼周礼名自实。","呜呼老翁言最直，乾坤梦幻人岂识。","狂夫此语休过劈，老翁作山假与真，我且向翁深一揖。"]},{"t":"祈晴有感为滁阳曾太守作","f":"七言古诗","c":["阴阳升降真何如，正蒙欲著吾无书。","胸中不饱龙眠马，老夫敢望张横渠。","环滁太守温如玉，古人黄宪今张黻。","祈晴大手西台文，千古为公刚一读。","空山破屋县青灯，天地至诚当果灵。","程氏遗书蠹鱼里，呼儿夜半寻金縢。"]},{"t":"马远画删去杨妹子题惧庵以余为俗","f":"七言古诗","c":["平生看画真模糊，一字不识之与无。","家藏古笔虽马远，两行细字其谁乎。","惧庵先生画中杰，一见心神便飞越。","凭陵大叫寻品题，俗眼谓余那认得。","九皋看马将无同，岂在牡牝玄黄中。","看画且须论画外，妇人软语徒匆匆。","牝鸡晨鸣家国丑，老夫此眼真俗否。"]},{"t":"题玉川画","f":"楚辞体","c":["江西老丁天造深，一树一石皆有法。","忽然得此奇人图，天下良工吾久瞎。","皴如马远翻老苍，势比董源还峭拔。","芾乎维乎空有名，谁能写此水两峡。","中间兀坐忽两翁，白发溪风若飘飒。","一人古貌而古裳，一人不巾而不袜。","欣然欲问此老谁，老丁已死谁能答。","我闻古亦有至人，非圣非愚亦非达。","茫乎蒙乎无所取，一兮混兮而不杂。","娄卷膻行已笑虞，非仁非义似嗤发。","世间万事只土块，何物斗筲堪用伐。","伊人石户岂其徒，不然亦是王与齧。","子州支父当佳哉，壶丘子林那易得。","世人固不知此流，许由巢父徒高节。","吮痈舐痔术已工，侈然秣马丹其辙。","痴奴老仆誇豪雄，达士先生殊不屑。","此波已倒虽莫收，钝牛未死犹堪策。","老丁老丁尔何人，世上小儿真豕虱。"]},{"t":"琼林宴归图","f":"七言古诗","c":["永清有仆双赤足，手持一画刚五幅。","自云此是琼林图，一幅主公真面目。","琼林宴罢醉归来，十里香尘马蹄速。","一日看尽长安花，柳汁宫袍春正绿。","望中隐隐宫阙深，万片綵云人一笏。","人间万事岂足荣，进士出身良可录。","进士出身良可录，台阁阿衡俱此卜。","从容一代真明良，万古朝堂正都咈。","人臣为报当何如，盛治岂容前史独。","愿言一拜各勉旃，稷契皋夔幸毋惑。"]},{"t":"夏太常画猫","f":"古风","c":["花竹蒙茸太湖畔，细细东风春欲转。","老狸明月睡正酣，玉漏无声夜将半。","乾坤万物理不诬，买鱼底用深相呼。","人间坐镇自雅俗，翻盆倒瓮何时无。","君不见一菜谁甘论藜藿，猛虎在山非自恶。"]},{"t":"钟钦礼画牛","f":"古风","c":["东风渺渺平原绿，几鼻浮江春带犊。","短蓑耕罢一犁归，数亩山陂雨初足。","薄田我亦耕定山，六角未能终日閒。","一笑还寻饮牛处，夕阳疏柳前溪湾。","君不见江山万古驱牛样，用则耕田閒则放。"]},{"t":"题刘侍御画","f":"古风","c":["东之太古英，老眼庖羲画。","文字六经前，心了不须读。","山川流峙鸢鱼中，看画得此将无同。","李成马夏何足数，此心直欲窥鸿蒙。","乾坤此卷忽披看，数点青山正浓淡。","眼中何处俗与真，一笑天机俱烂漫。","世人见画空茫然，安知画外无真传。","先生万古有真趣，白头还我羲皇天。","古文篆籀藏科斗，我羡东之不容口。","尚书宅里闻剧谈，天地斯人世何有。","人间一默归玄元，老夫更欲观无言。","手持此卷已一月，病回阁笔城东轩。"]},{"t":"溪云水碓短歌行","f":"七言绝句","c":["山中水碓活水中，老夫起坐观无穷。","源头活水不用借，活水自舂无日夜。"]},{"t":"题画凤","f":"古风","c":["凤凰非圣世不生，非竹实不食，非梧桐不鸣。","比之为太华、为沧溟，应之为文明。","得之为干戈息、为天下太平。","古今四海谁与盟，姚江两蔡当代英。","乾坤到处有高名，画中吕纪称两京，回头天地须此评。","翩翩两凤凰，忽尔飞丹青。","偶然见者无不惊，皆言摹拟真绝精。","呜呼，皆言摹拟真绝精，吾于两蔡心忽倾。","虞廷老凤快一睹，箫韶天地终九成。","岐山万古更忽此，文王一怒西周兴。","舜有二十八相，武王曰予有乱臣十人，其世瑞，其数宁。","皆可以为麒麟、为凤凰、为庆云、为景星。","方今尧舜正在上，乐和礼备刑更清。","嗟夫姚江蔡氏两夫子，慎勿负所学孤朝廷。"]},{"t":"题海阳谢氏族谱后","f":"古风","c":["海阳谢氏谱牒存，万古世系称名门。","至今不绝乃如线，祖武绳绳还子孙。","南雍上舍真文胄，人物元为谢家秀。","不知苗裔果出谁，想只东山谢安后。","欲将孝悌油然兴，远寻族谱苏氏亭。","表章且此求大作，谁为天下名公卿。","咀嚼莺花老牙痛，天地一丸吾自弄。","人生万事须勉为，文字他人空借重。","君不见仲尼谱系果亦真，乾坤万古今一人。"]},{"t":"诚斋卷","f":"七言古诗","c":["圣贤一脉传无穷，谁家灯火西窗红。","韦编断尽蠹鱼走，中庸岂在书版中。","于穆此天吾一理，周孔羲文长不死。","此斋一过一悚然，白发披披已垂耳。","为尧为舜无古今，天人分数谁复深。","莫怪不知杨万里，草庐文字子思心。"]},{"t":"江游","f":"五言绝句","c":["秋来乘艇子，出浦更悠然。","鸟白江初阔，天空月正圆。"]},{"t":"和杜韵 其一","f":"五言绝句","c":["山晚溪喧减，天秋月放多。","棹歌如未起，其奈老夫何。"]},{"t":"和杜韵 其二","f":"五言绝句","c":["有诗俱月底，无酒不松根。","问我今何处，尧天击壤村。"]},{"t":"和杜韵 其三","f":"五言绝句","c":["老翠山皆洞，深红树颇花。","人誇仙世界，我笑是贫家。"]},{"t":"细雨 其一","f":"五言绝句","c":["细雨摊书卷，风花坐晚轩。","开笼拜鹦鹉，鹦鹉会人言。"]},{"t":"细雨 其二","f":"五言绝句","c":["短帽花能舞，长歌袖亦轩。","䦧墙诗最好，不是圣人言。"]},{"t":"细雨 其三","f":"五言绝句","c":["默默閒思坐，萧然閒此轩。","田家荆树好，好亦不须言。"]},{"t":"细雨 其四","f":"五言绝句","c":["俯仰无穷乐，春风一草轩。","此心还大舜，不见有流言。"]},{"t":"题画 其一","f":"五言绝句","c":["道人一片心，云水活泼泼。","何处问天机，天机此秋阁。"]},{"t":"题画 其二","f":"五言绝句","c":["坐亦岂非行，行亦岂非坐。","问我我不言，笑舞溪云破。"]},{"t":"题兰 其一","f":"五言绝句","c":["幽兰在南坡，爱之亦何趣。","为爱幽兰香，须识香来处。"]},{"t":"题兰 其二","f":"五言绝句","c":["此兰我何爱，对之终日坐。","万物我一兰，天地乃一我。"]},{"t":"活水亭杂诗 其一","f":"五言绝句","c":["出门山水游，小孙每相喜。","殷勤捧鸠藤，请与老翁拄。"]},{"t":"活水亭杂诗 其二","f":"五言绝句","c":["读书眼已花，半板未能过。","只向小藤床，闭眼终日坐。"]},{"t":"活水亭杂诗 其三","f":"五言绝句","c":["布褐聊自温，豆粥长一饱。","只此深山居，逍遥以终老。"]},{"t":"题孙痴春草","f":"五言绝句","c":["未了物何我，了了我一物。","道人活泼心，一片西窗绿。"]},{"t":"题沈石田画鹅为文元作 其一","f":"五言绝句","c":["天机我不言，言之欲谁领。","柳塘春水深，弄此白鹅影。"]},{"t":"题沈石田画鹅为文元作 其二","f":"五言绝句","c":["老鹅秋菊中，我欲画几画。","万古天地间，且让庖羲独。"]},{"t":"寄娄一斋 其一","f":"五言绝句","c":["炯炯平生心，白日青天在。","深山南斗高，无夜不再拜。"]},{"t":"寄娄一斋 其二","f":"五言绝句","c":["江门风月诗，莲塘水花趣。","安得二先生，倾倒鹅湖寺。"]},{"t":"寄娄一斋 其三","f":"五言绝句","c":["朱学本不烦，陆学亦非简。","先生一笑中，皓月千峰晚。"]},{"t":"寄娄一斋 其四","f":"五言绝句","c":["斯文久寂寥，所望未云绝。","一夜老头颅，添却千茎白。"]},{"t":"江湖胜览","f":"五言绝句","c":["江湖万里船，天地双老脚。","笑我不出门，一个天峰阁。"]},{"t":"题画 其一","f":"五言绝句","c":["一雪正如此，乾坤何处看。","都将无极妙，千古一凭阑。"]},{"t":"题画 其二","f":"五言绝句","c":["千古关仝画，江山意不穷。","老将无画意，今且问关仝。"]},{"t":"题画 其三","f":"五言绝句","c":["天地一驴子，溪山坐晚烟。","古谁先有意，画我过前川。"]},{"t":"题画 其四","f":"五言绝句","c":["太极吾焉妙，圈来亦偶誇。","此翁江阁路，骑雪又梅花。"]},{"t":"静观亭为南川先生题 其一","f":"五言绝句","c":["睡起湖亭坐，乾坤意自深。","青天无一滓，明月在波心。"]},{"t":"静观亭为南川先生题 其二","f":"五言绝句","c":["万物无无里，斯亭亦偶然。","道人閒不过，聊尔弄湖天。"]},{"t":"静观亭为南川先生题 其三","f":"五言绝句","c":["微月此波寂，远峰何处青。","我来閒与坐，不记是谁亭。"]},{"t":"题梦白莲池诗","f":"五言绝句","c":["赋诗白莲池，梦中聊尔尔。","寄谢无极翁，此吾梦中语。"]},{"t":"施孝子","f":"五言绝句","c":["天下本无孝，人间曾闵多。","谁将施孝子，一咏老夫歌。"]},{"t":"改施公正执庵为程庵 其一","f":"五言绝句","c":["天地无穷担，头昏老病深。","我无衣与钵，聊寄百年心。"]},{"t":"改施公正执庵为程庵 其二","f":"五言绝句","c":["明道虽人人，君须爱明道。","莫笑庄定山，徒能改君号。"]},{"t":"翎毛","f":"五言绝句","c":["何处乾坤妙，天机各洒然。","相看今满眼，老子更何言。"]},{"t":"题画","f":"五言绝句","c":["远山青两峰，老树红一叶。","我怀不可羁，空江下明月。"]},{"t":"题萧尹翎毛 其一","f":"五言绝句","c":["幽鸟啼自哀，秋风竹枝怨。","哀怨情岂胜，月明寒影乱。"]},{"t":"题萧尹翎毛 其二","f":"五言绝句","c":["佳木求幽鸟，幽鸟求佳木。","佳木与幽鸟，感叹白头秃。"]},{"t":"题萧尹翎毛 其三","f":"五言绝句","c":["一见雪满颅，能不怀平生。","谁将单父台，画此作西铭。"]},{"t":"题萧尹翎毛 其四","f":"五言绝句","c":["感兹原上情，相倾或相顾。","老我空此心，爱亦莫能助。"]},{"t":"送博罗何孝子 其一","f":"五言绝句","c":["赠别疏篱下，冬来菊又残。","只惟三两朵，留着自家看。"]},{"t":"送博罗何孝子 其二","f":"五言绝句","c":["白酒江门暖，北来风正寒。","酿方君不录，明日寄书难。"]},{"t":"送博罗何孝子 其三","f":"五言绝句","c":["万事都难问，相逢坐夜阑。","寒灯青的的，莫照酒杯乾。"]},{"t":"送博罗何孝子 其四","f":"五言绝句","c":["人间何孝子，此日更求官。","何以江门老，无诗送子完。"]},{"t":"友泉","f":"五言绝句","c":["一体乾坤妙，诸君且未知。","已将无限意，分付友山诗。"]},{"t":"玉溪为谢汝申作","f":"五言绝句","c":["何哉川上心，欲语还自默。","安得玉溪翁，问我溪中月。"]},{"t":"梅花","f":"五言绝句","c":["梅花一太极，老我一梅花。","点笔无言坐，寒溪月满槎。"]},{"t":"骑驴浮海图和韵","f":"五言绝句","c":["堂堂白日中，鬼怪何用见。","谁乎江海游，不趁风帆便。"]},{"t":"海棠双喜","f":"五言绝句","c":["不有平生戚，安能极称时。","无边此花鸟，方是野人诗。"]},{"t":"松风","f":"五言绝句","c":["何处清风里，长松古县门。","海风吹不断，明月满乾坤。"]},{"t":"题画","f":"五言绝句","c":["百年图凤心，空江坐头白。","只有古青天，还我磻溪月。"]},{"t":"题小画 其一","f":"五言绝句","c":["何处戏场中，閒来舞独速。","放下鬼脸儿，俱是真面目。"]},{"t":"题小画 其二","f":"五言绝句","c":["数声老瓦盆，一曲古村篴。","熙熙歌舞中，不知皆帝力。"]},{"t":"题小画 其三","f":"五言绝句","c":["输赢每自如，万事亦何有。","君且莫扬拳，输还酌吾酒。"]},{"t":"题小画 其四","f":"五言绝句","c":["蛇麻失其性，道眼真不花。","我当幻中见，天地皆蛇麻。"]},{"t":"谢氏八景 其一 芙蓉卓笔","f":"五言绝句","c":["万古写不停，玄天无一墨。","我欲往从之，苍苍本无色。"]},{"t":"谢氏八景 其二 华盖仙踪","f":"五言绝句","c":["亭亭一华盖，仙踪长万古。","万古一六经，六经一尼父。"]},{"t":"谢氏八景 其三 南山拱秀","f":"五言绝句","c":["南山天地中，千古一拔萃。","此秀真泰山，当出尼轲辈。"]},{"t":"谢氏八景 其四 北沼涵清","f":"五言绝句","c":["一泓北沼深，涵泳在天地。","何自真不污，孕兹龙马处。"]},{"t":"谢氏八景 其五 象岭朝阳","f":"五言绝句","c":["何处观朝阳，日日天东极。","吾人孤凤鸣，长向朝阳立。"]},{"t":"谢氏八景 其六 泷冈夜月","f":"五言绝句","c":["吾心万古天，明月一池水。","以心观吾心，吾心是如此。"]},{"t":"谢氏八景 其七 苍松竞秀","f":"五言绝句","c":["谢家芝兰庭，更着几松盖。","堂堂老翠圆，撑住青天在。"]},{"t":"谢氏八景 其八 丹桂秋香","f":"五言绝句","c":["秋香五株桂，谢氏还几株。","要识乾坤中，鲁国今一儒。"]},{"t":"题菊","f":"五言绝句","c":["莽莽乾坤雨，秋香岂未知。","秋风将短鬓，千古一东篱。"]},{"t":"题画 其一","f":"五言绝句","c":["浮云笼晚照，野树亦轻阴。","莫道无人迹，春山也自深。"]},{"t":"题画 其二","f":"五言绝句","c":["昔日千年调，而今两秃翁。","都将无限意，高坐钓船中。"]},{"t":"题画 其三","f":"五言绝句","c":["静坐方虚极，开门江月深。","梅花今夜好，天地亦吾心。"]},{"t":"挽查姓民 其一","f":"五言绝句","c":["公恩在燕北，更活江西命。","问余何以知，冷庵印公印。"]},{"t":"挽查姓民 其二","f":"五言绝句","c":["公在春在公，公死春何处。","门前病鬼冤，哭倒红杏树。"]},{"t":"挽查姓民 其三","f":"五言绝句","c":["人生既已死，生理那可得。","千古一孤坟，空山落寒月。"]},{"t":"浣灵卷为当涂李都宪作 其一","f":"五言绝句","c":["朝浣浣此灵，暮浣浣此灵。","汤铭此谁后，得见当涂英。"]},{"t":"浣灵卷为当涂李都宪作 其二","f":"五言绝句","c":["浣天天光明，浣地地历陆。","大哉吾一心，浣浣圣贤出。"]},{"t":"浣灵卷为当涂李都宪作 其三","f":"五言绝句","c":["万古天地中，此脉未应绝。","拜读浣灵诗，一夜头尽白。"]},{"t":"茅林八景 其一 太山拥翠","f":"五言绝句","c":["云水阁云峰，斜通幽鸟径。","巨石莫相寻，茏葱看隐映。"]},{"t":"茅林八景 其二 曲港拖蓝","f":"五言绝句","c":["九皋昨夜露，孤鹤散清响。","惊起弄波人，长啸星河上。"]},{"t":"茅林八景 其三 林溪渔钓","f":"五言绝句","c":["白头据盘石，长竿弄烟水。","为问梦中怨，孰与溪鱼美。"]},{"t":"茅林八景 其四 禅寺晚钟","f":"五言绝句","c":["暝翳寒城雨，明催古路人。","胸中纷扰梦，断我几黄昏。"]},{"t":"茅林八景 其五 龙潭秋月","f":"五言绝句","c":["神物本天用，寒山深见底。","不得抱珠眠，明年春雨里。"]},{"t":"茅林八景 其六 牛陇春云","f":"五言绝句","c":["野外如膏雨，天边披絮云。","眼前春事急，公是耦耕人。"]},{"t":"茅林八景 其七 竹轩诗兴","f":"五言绝句","c":["列国坛皆废，千年风未开。","洋洋兼沨沨，季子几时来。"]},{"t":"茅林八景 其八 芝馆书声","f":"五言绝句","c":["平生用不尽，古人一卷书。","持此争愚圣，今人万卷馀。"]},{"t":"九鹭图","f":"七言绝句","c":["白雪数拳元自好，老夫门外一江清。","沧洲倚杖忽相近，晚日青天吾眼明。"]},{"t":"食豇","f":"七言绝句","c":["一畦微雨净无尘，紫豆银茄更可人。","观物亭中聊一饱，先生真个是清贫。"]},{"t":"石翁见寄次韵 其一","f":"七言绝句","c":["逍遥游侣远来寻，万仞烟霞一片心。","难向眼前人说得，眼前人只解乡音。"]},{"t":"石翁见寄次韵 其二","f":"七言绝句","c":["山盟投老会相寻，无复人间不了心。","铁笛试吹峰顶月，山灵依旧是知音。"]},{"t":"新岁寄雷德舆 其一","f":"七言绝句","c":["西舍东邻笑接筵，与君歌舞最留连。","风流一段丹青兴，不动而今十五年。"]},{"t":"新岁寄雷德舆 其二","f":"七言绝句","c":["梅花当户酒当筵，花笑孤斟影不连。","不见及时行乐伴，独将新句伴新年。"]},{"t":"题县主山水画 其一","f":"七言绝句","c":["家具生涯且钓舟，黄公台影漾浮沤。","波心间有鸱夷笑，不把牙筹碍钓钩。"]},{"t":"题县主山水画 其二","f":"七言绝句","c":["水旆山幢到眼真，丹青笔手压红尘。","休衙午睡千峰面，江北江南一样春。"]},{"t":"题松筠诗卷","f":"七言绝句","c":["满城二月花惊眼，风雨寻常便打残。","雪冷江空何日是，来人真忆二公难。"]},{"t":"读谢叠山与刘忠斋书","f":"七言绝句","c":["尽把夷齐许后身，荐贤当日果何人。","山中宋史人希见，元是忠斋也宋臣。"]},{"t":"寄新昌王乐用侍御 其一","f":"七言绝句","c":["白头放酒太平春，君舞蓑衣我钓纶。","可是山人能共闼，山人元是老山人。"]},{"t":"寄新昌王乐用侍御 其二","f":"七言绝句","c":["落花闻道满苍苔，可是东风又许开。","洞里白云虽泠淡，不教容易出山来。"]},{"t":"题江湖逸兴卷","f":"七言绝句","c":["江波閒弄打鱼船，酒醒狂歌酒醉眠。","分付蓑衣休舞破，他时留着补青天。"]},{"t":"平斋为南昌刘司训作","f":"七言绝句","c":["称量万事与均停，君在南昌主六经。","莫笑老生随起倒，我家秤却是无星。"]},{"t":"寄詹大尹","f":"七言绝句","c":["一县春风万县同，经纶试手历城公。","白头到我思君处，笑倚长镵豆垄中。"]},{"t":"读杨时秀诗集","f":"七言绝句","c":["江湖此卷三千首，今古何年二百春。","明日会寻留鹤老，北山灯火拜刘因。"]},{"t":"姚御史画竹石为周景明作","f":"七言绝句","c":["洋州食画惟两竿，米老见之须一拜。","景明对此真何如，草阁秋江明月在。"]},{"t":"枯木竹石","f":"七言绝句","c":["万里乾坤冰雪中，百年心事几人同。","二公只恐徐刘是，死恋厓山老秃翁。"]},{"t":"钓鱼图 其一","f":"七言绝句","c":["谁拈秃笔写渔船，我作渔翁又十年。","画里欲寻谁是我，白头高帽顶青天。"]},{"t":"钓鱼图 其二","f":"七言绝句","c":["何处烟波满钓翁，桃花流水各溪红。","而今合是唐虞世，都在尧天荡荡中。"]},{"t":"谢陈汉崇少参历日","f":"七言绝句","c":["甲子书来问钓舟，江边草木领春秋。","野人不作经纶梦，笑撚花枝坐白头。"]},{"t":"石衢 其一","f":"七言绝句","c":["裁成白首全无用，默坐高斋几石衢。","肯笑老人迂阔甚，买田为井亦横渠。"]},{"t":"石衢 其二","f":"七言绝句","c":["十里徽人藉此翁，车徒真免哭途穷。","病夫只有閒中计，万古乾坤大道中。"]},{"t":"题吴山春景画","f":"七言绝句","c":["风光曾记拥肩舆，花柳无穷一笑馀。","为说驴鸣公案在，乾坤真个有横渠。"]},{"t":"渊明 其一","f":"七言绝句","c":["圣贤自古在知几，膰肉那知女乐非。","问我当年陶靖节，柴桑可是折腰归。"]},{"t":"渊明 其二","f":"七言绝句","c":["五柳清风一布袍，百年风味也吾曹。","古人岂必今人是，且放先生酒处高。"]},{"t":"赠容一之别和白沙先生","f":"七言绝句","c":["江蓑许共白鸥群，万里秋帆又水云。","不是苦留君不住，老夫无地可留君。"]},{"t":"君忍为白沙门人倪圣祥作","f":"七言绝句","c":["世事百年谁适意，须君空洞一毫无。","白沙门地皆沧海，莫下长江问老夫。"]},{"t":"送林秋官谪滇南和韵","f":"七言绝句","c":["一点浮云眼已过，滇南明日未蹉跎。","丈夫气节前头路，敢向先生拜说多。"]},{"t":"题渊明归庄图 其一","f":"七言绝句","c":["眼中晋鼎睨谁频，五柳归来别有春。","若把君臣徒造次，辙环天下是何人。"]},{"t":"题渊明归庄图 其二","f":"七言绝句","c":["万古人心万古看，中原如此可能安。","先生醉倒东篱意，得恐驱驰老病难。"]},{"t":"送直夫陈侍御 其一","f":"七言绝句","c":["芙蓉秋水与诗清，御史平生极有情。","若道此花真个好，老夫还折赠先生。"]},{"t":"送直夫陈侍御 其二","f":"七言绝句","c":["白头骢马与垂纶，一曲梅花太古春。","高坐庐山三万丈，谁知弹与不弹人。"]},{"t":"寄淮安邝同府","f":"七言绝句","c":["江雨黄紬梦觉时，行藏肯与别人知。","秋来若见江门月，读烂前年送别诗。"]},{"t":"赠溧阳费医","f":"七言绝句","c":["帝伯皇王事不疑，痬医又是小儿医。","而今肯作华胥梦，须遣江南扁鹊知。"]},{"t":"奉亲堂为古溪赋","f":"七言绝句","c":["孝子人间果是非，肯堂春酒白鱼肥。","程家二子平生计，只有吟风弄月归。"]},{"t":"三江渔樵卷","f":"七言绝句","c":["水月山云可认真，三江人醉古冈春。","一双我有平生眼，看尽人间几样人。"]},{"t":"题画竹林七贤","f":"七言绝句","c":["放酒溪山此数翁，长拚潦倒醉春风。","先生亦有疏狂意，只在随花傍柳中。"]},{"t":"题林良画史沧海亭","f":"七言绝句","c":["送老西家画益奇，江门花鸟是谁诗。","此亭得恐真风月，画外无人别有知。"]},{"t":"题菜","f":"七言绝句","c":["物物乾坤一雨新，小园今日意全真。","许谁说与窗前草，不是人间别有春。"]},{"t":"承惧庵先生题定山溪云亭和韵","f":"七言绝句","c":["笑只溪云是我山，百年那爱此亭閒。","匆匆但恐霖难作，飞去人间不易还。"]},{"t":"奉荅司马提学 其一","f":"七言绝句","c":["行藏牛背把书行，老子能无后学情。","木铎肯教天不管，羊裘也可累先生。"]},{"t":"奉荅司马提学 其二","f":"七言绝句","c":["画本烟霞迹已殊，且将行止问何如。","后生误恐寻真样，也堕深山鹿豕居。"]},{"t":"奉荅司马提学 其三","f":"七言绝句","c":["万古经书万古明，圣贤言语圣贤情。","乾坤倘与人描画，日月山川想更精。"]},{"t":"奉荅司马提学 其四","f":"七言绝句","c":["风花舞弄江亭月，水石烟花共酒缘。","老我醉中都忘却，是谁吾道是谁禅。"]},{"t":"奉荅司马提学 其五","f":"七言绝句","c":["正道妖风不两能，是非千古自分明。","与公且把无穷意，分付江流月满庭。"]},{"t":"忆秉常","f":"七言绝句","c":["天北天南且梦君，一杯何此隔江云。","五更哦得相思句，只有梅花月最闻。"]},{"t":"陵阳山人","f":"七言绝句","c":["天地斯人术比精，白头何限古今情。","尼丘肯与陵阳别，万古斯文只子平。"]},{"t":"赠黄池袁义官","f":"七言绝句","c":["西江一斗依违里，短褐高轩激宕中。","我度与公同一大，许酣天地作春风。"]},{"t":"梅花 其一","f":"七言绝句","c":["天风何步此西湖，偶把梅花醉一涂。","笑我十年书卷废，也拈秃笔注河图。"]},{"t":"梅花 其二","f":"七言绝句","c":["此机造化如真语，混沌谁能更凿之。","周子不知天亦妙，乃圈太极与人知。"]},{"t":"送董孟吉 其一","f":"七言绝句","c":["真州闻已片帆东，五马何来草屋中。","万里故人还一见，老夫当拜打头风。"]},{"t":"送董孟吉 其二","f":"七言绝句","c":["今昔总无悲与喜，浮云万事谅能谙。","肯将万里乌蒙意，来醉青山活水南。"]},{"t":"送董孟吉 其三","f":"七言绝句","c":["日午来过到日昏，短蓑钓石坐能温。","不惭活水贫家淡，也劝山瓢带月吞。"]},{"t":"读文山别集 其一","f":"七言绝句","c":["感慨文山别集章，白头老泪几淋浪。","若言君父无情者，除是当年赵子昂。"]},{"t":"读文山别集 其二","f":"七言绝句","c":["殷士周家亦可推，大元此老杀何为。","我知世祖终宽厚，天授非人识者谁。"]},{"t":"读文山别集 其三","f":"七言绝句","c":["神在知几道亦行，存亡进退古今情。","堂堂如此文山辈，要亦人间万古英。"]},{"t":"题静学卷 其一","f":"七言绝句","c":["天机满眼欲谁看，到处逢人一语难。","此学平生真问我，无弦琴自不须弹。"]},{"t":"题静学卷 其二","f":"七言绝句","c":["妙极吾心果到时，傍花随柳也无诗。","五经若谓真糟粕，只恐人间未尽知。"]},{"t":"题静学卷 其三","f":"七言绝句","c":["太极乾坤自古今，许将图说到谁深。","白头万古翻公案，惟有元公得我心。"]},{"t":"题静学卷 其四","f":"七言绝句","c":["古今吾道本难精，每与空虚佛老争。","肯识一毫千里意，人间真拜李延平。"]},{"t":"挽吴吕山 其一","f":"七言绝句","c":["古今生灭谁与言，十二万年天一元。","道人欲作吕山哭，一溪明月湖东轩。"]},{"t":"挽吴吕山 其二","f":"七言绝句","c":["春风流荡吕山歌，野月肩舆到已多。","转首烟花虽易别，老天留与太湖波。"]},{"t":"送小儿会乡试 其一","f":"七言绝句","c":["窗纸还涂丙子鸦，人间裘冶未须誇。","明朝领取君恩处，莫画青山旧样花。"]},{"t":"送小儿会乡试 其二","f":"七言绝句","c":["尧天一屋尽容安，万丈须还寸补看。","分付诸顽须汝是，菜羹休顾老夫难。"]},{"t":"送小儿会乡试 其三","f":"七言绝句","c":["人间万事可终閒，更际明良拜舞间。","我病既深扶不起，吾儿何敢亦青山。"]},{"t":"送小儿会乡试 其四","f":"七言绝句","c":["桂花一树几人分，吃著三场应举文。","富贵汝知何物是，浮云之外且浮云。"]},{"t":"华亭金藻休宁汪循上海张澡诸友枉顾定山且索一言于其别诗以道意 其一","f":"七言绝句","c":["庭草真传到晦翁，无端万紫与千红。","可知肝胆朱门学，不在经书传注中。"]},{"t":"华亭金藻休宁汪循上海张澡诸友枉顾定山且索一言于其别诗以道意 其二","f":"七言绝句","c":["风月无边问荅时，青山活水满吾诗。","若除流动天机外，老子平生自不知。"]},{"t":"华亭金藻休宁汪循上海张澡诸友枉顾定山且索一言于其别诗以道意 其三","f":"七言绝句","c":["斯道乾坤自古今，濂溪主静独吾心。","孔颜乐处真何事，愿与诸贤更一寻。"]},{"t":"华亭金藻休宁汪循上海张澡诸友枉顾定山且索一言于其别诗以道意 其四","f":"七言绝句","c":["举业经书也圣功，人间道眼费圆融。","夜来睡醒罗浮梦，月满秋江数十峰。"]},{"t":"司训廖先生家观菊 其一","f":"七言绝句","c":["睡起疏篱点物华，四三童冠几黄花。","浴沂此日秋光里，不属曾家属廖家。"]},{"t":"司训廖先生家观菊 其二","f":"七言绝句","c":["年年老菊费栽难，每到秋来借倚阑。","老我白云红树子，如今都作此花看。"]},{"t":"司训廖先生家观菊 其三","f":"七言绝句","c":["短篱黄菊满秋晖，把酒相看醉不违。","却道我家元自有，帽檐不与一枝归。"]},{"t":"司训廖先生家观菊 其四","f":"七言绝句","c":["秋光莽莽到东篱，要识陶家以外诗。","倘把傲霜徒自看，此花天妙没人知。"]},{"t":"司训廖先生家观菊 其五","f":"七言绝句","c":["花到金相玉质精，真纯和粹更幽清。","凭谁笑与梅花说，且合推尊作大成。"]},{"t":"司训廖先生家观菊 其六","f":"七言绝句","c":["圣池长共此花评，一句清深万古灵。","天味倘知真个好，欲和朝露咽先生。"]},{"t":"司训廖先生家观菊 其七","f":"七言绝句","c":["太极人间物物新，龟书龙马各精神。","泮池我爱三夫子，认得黄花绿叶真。"]},{"t":"司训廖先生家观菊 其八","f":"七言绝句","c":["天意秋香未肯涯，绕篱黄白尽容誇。","物中若道无凡圣，岂有人间不落花。"]},{"t":"雪雁","f":"七言绝句","c":["江山万里雪如此，老雁北风何处滩。","欲识阴阳千古梦，乾坤聊在睡中看。"]},{"t":"雪兔","f":"七言绝句","c":["人间物物天何碍，老兔泉声亦妙如。","笑我天机无点处，白头拈笔是鸢鱼。"]},{"t":"半山亭 其一","f":"七言绝句","c":["一墩千古且閒争，拗鬼何知更此平。","蕉鹿也知真梦梦，此亭吾恐亦虚名。"]},{"t":"半山亭 其二","f":"七言绝句","c":["老眼苍茫醉欲还，数椽聊复半山间。","谁家亭子青天上，只属虚空不属山。"]},{"t":"思亲楼","f":"七言绝句","c":["乾坤了尽了何如，怪伟公然一大书。","明日肯君参欲破，老拳搥碎此楼居。"]},{"t":"友山","f":"七言绝句","c":["一语乾坤更几关，白头师友恐须閒。","友山若问真何说，万古中间我一山。"]},{"t":"题江村卷","f":"七言绝句","c":["溪山驴背不藏春，花柳东风眼自真。","道得程家新句子，老夫今日拜何人。"]},{"t":"送王判簿归蜀时萧尹在邑 其一","f":"七言绝句","c":["世务閒闻到寂寥，鸺鹠潦草得鹪鹩。","谁真笑我长镵柄，斸断山腰枸菊苗。"]},{"t":"送王判簿归蜀时萧尹在邑 其二","f":"七言绝句","c":["僻坞桃花已失公，买刀何许更相逢。","饿夫半勺秋来梦，须绕巫山十二峰。"]},{"t":"送王判簿归蜀时萧尹在邑 其三","f":"七言绝句","c":["片语丰干偶觉违，一年风雨几柴扉。","可知老子黄山月，也送巴江万里归。"]},{"t":"上西华山先陇 其一","f":"七言绝句","c":["丱髻殷忧遽海涯，松吴来梦几江花。","那知此道千年拜，我祖青天是起家。"]},{"t":"上西华山先陇 其二","f":"七言绝句","c":["汉老乾坤日月光，一亭千古几纲常。","也谁知此鸥波地，更与颓风大主张。"]},{"t":"上西华山先陇 其三","f":"七言绝句","c":["万古平章与后先，馂馀唐汉总垂涎。","可知花柳乾坤里，我祖风流六十年。"]},{"t":"上西华山先陇 其四","f":"七言绝句","c":["针芥劳劳漫古今，几徒鱼水草庐心。","千年独有精英槩，不与青山壳子深。"]},{"t":"上西华山先陇 其五","f":"七言绝句","c":["抔土长埋盖世姿，西华撼动小孙诗。","终身诸葛无人识，聊与青山绿水知。"]},{"t":"上西华山先陇 其六","f":"七言绝句","c":["孙翁衣钵只中庸，马仆牛医奠酒同。","我辈不知谁是伋，松梢擘纸挂西风。"]},{"t":"上西华山先陇 其七","f":"七言绝句","c":["遗编甫律也翱文，世难寥寥只此坟。","不识我来谁与看，江风天摆万秋云。"]},{"t":"上西华山先陇 其八","f":"七言绝句","c":["江蓑水月老还披，许大乾坤一片碑。","千古无船横钓濑，墓门能拜子陵谁。"]},{"t":"寄沈慎之 其一","f":"七言绝句","c":["雁荡天台且未堪，春潮能许挂江帆。","空山十丈丹厓里，一个痴人一草庵。"]},{"t":"寄沈慎之 其二","f":"七言绝句","c":["老拙元无半寸长，逢君不语只空狂。","白头静里焚香坐，长记移舟过溧阳。"]},{"t":"子陵钓鱼图","f":"七言绝句","c":["行止丘轲总未裁，江波祗个钓鱼台。","谁知也有渔舟画，不照严光影子来。"]},{"t":"挽香岩和尚为僧寂庵作 其一","f":"七言绝句","c":["来来去去非真幻，此理人间本妙哉。","公是寂庵吾敢问，师今何去昔何来。"]},{"t":"挽香岩和尚为僧寂庵作 其二","f":"七言绝句","c":["钟声谁打定中魂，那有三才别立根。","我正问公公已死，岂胜哀泪洒乾坤。"]},{"t":"挽香岩和尚为僧寂庵作 其三","f":"七言绝句","c":["死却香岩未可谈，个中何者不香岩。","静无动有吾何说，试著西庵老寂参。"]},{"t":"赠星命者和东白先生","f":"七言绝句","c":["人间几许卧谁龙，谈命谈星半醉中。","且莫相逢开口易，老夫富贵是苓通。"]},{"t":"梅花 其一","f":"七言绝句","c":["元自贞来妙亦深，梅花何处见天心。","凭谁说与尧夫老，莫向乾坤子半寻。"]},{"t":"梅花 其二","f":"七言绝句","c":["草阁半床疏影月，梅花今夜妙何如。","老夫自起焚香坐，周易谁知不在书。"]},{"t":"梅花 其三","f":"七言绝句","c":["一花太极一丸春，何梦林逋看未真。","自有暗香疏影句，相知千古是何人。"]},{"t":"梅花 其四","f":"七言绝句","c":["一白已为天下绝，千红还许独开先。","若将齿角丘轲论，野店山桥亦老天。"]},{"t":"梅花 其五","f":"七言绝句","c":["图绘相逢已太频，天谁传说许前身。","白头岂误和盐梦，只恐匆匆画未真。"]},{"t":"梅花 其六","f":"七言绝句","c":["菊花曾许是龟书，岂有寒梅不共之。","周子通书程子易，孙翁须爱紫薇诗。"]},{"t":"梅花 其七","f":"七言绝句","c":["罗浮真兴许谁狂，暗暗频通万古香。","昨夜酒醒何处梦，五更霜月满溪堂。"]},{"t":"梅花 其八","f":"七言绝句","c":["真香妙影舞溪园，每共山人月一轩。","全体等閒俱露却，莫言天地不能言。"]},{"t":"梅花 其九","f":"七言绝句","c":["天妙相逢几称情，平生老菊尚渊明。","千年著放莲花眼，莫遣南枝气不平。"]},{"t":"题僧惠堂卷 其一","f":"七言绝句","c":["此公元自一仁来，根向三才肯别栽。","散得人间真种子，乾坤花满万灵台。"]},{"t":"题僧惠堂卷 其二","f":"七言绝句","c":["摩顶阎浮手欲痡，不知曾惠自家无。","明朝且把收归我，康济乾坤一丈夫。"]},{"t":"题僧惠堂卷 其三","f":"七言绝句","c":["真惠凭谁问且真，百年偶醉十窝春。","定知老秃明朝顶，模著陈纲太极巾。"]},{"t":"落梅","f":"七言绝句","c":["不从贞处不看元，玉篴春风总浪言。","明日中间仁一点，始知开落是同原。"]},{"t":"梅花","f":"七言绝句","c":["尽遣东风问化工，南枝何与北枝同。","谁知无限春消息，都在寒烟一抹中。"]},{"t":"竹梅","f":"七言绝句","c":["神翠真红万古妍，化机相与荡何天。","披图多少尼丘梦，空有乾坤雪满颠。"]},{"t":"鸡冠花","f":"七言绝句","c":["古今物物疑相似，一体乾坤到几人。","笑把天峰秋色看，万红何片不同真。"]},{"t":"红梅","f":"七言绝句","c":["万物相形本各真，东风何意醉花神。","相看道眼休轻乱，白白红红总是春。"]},{"t":"萱草 其一","f":"七言绝句","c":["何闻謦欬不羹墙，曾与忘忧树北堂。","留得孤儿千古泪，不知忧在几时忘。"]},{"t":"萱草 其二","f":"七言绝句","c":["何处空堂梦欲残，白头片萼偶相看。","可胜精卫无穷恨，沧海填乾泪也乾。"]},{"t":"代弟孔高荅大中时游香泉","f":"七言绝句","c":["天纳吾家古朴城，祗将顽钝学痴兄。","知君不误真衣钵，付与溪山执屦行。"]},{"t":"题徐端本画","f":"七言绝句","c":["云水草亭閒自荡，风花老子动相随。","如今我问徐端本，一体乾坤却画谁。"]},{"t":"题画朱永隆吴大宜求","f":"七言绝句","c":["两眼堪盲病老穷，横云当面唾青松。","大风可怪悲歌甫，卷我山茅屋几重。"]},{"t":"寄司马先生 其一","f":"七言绝句","c":["溪云曾每拜公来，共我渔蓑滥钓台。","万里不知皇极手，谁家今又点蓬莱。"]},{"t":"寄司马先生 其二","f":"七言绝句","c":["书来无语不言还，出处谁能付等閒。","公有鸢飞鱼跃意，武夷山亦会稽山。"]},{"t":"寄司马先生 其三","f":"七言绝句","c":["糟粕将无此学看，三年一语听终难。","白头肯许相忘地，更与濂溪拜肺肝。"]},{"t":"寄司马先生 其四","f":"七言绝句","c":["别无书寄去无诗，形迹俱忘老病时。","昨夜朱弦弹绝意，只惟溪月洞云知。"]},{"t":"题画 其一","f":"七言绝句","c":["一猎何心更许驰，此中天妙只天知。","谁知满眼溪云趣，不在庖羲画卦时。"]},{"t":"题画 其二","f":"七言绝句","c":["若此烟云若此山，岂无版筑个人閒。","不知画者今何意，只画天松屋数间。"]},{"t":"完节堂","f":"七言绝句","c":["玉镜空台一片秋，古风高月也全收。","兔园何自须眉地，篱落遮阑补未周。"]},{"t":"钓台图","f":"七言绝句","c":["领得尧夫七尺纶，白头终荡五湖春。","千罾宁也鱼难得，断不移舟下孟津。"]},{"t":"红梅","f":"七言绝句","c":["春雨东风色未寒，杏花曾笑北人看。","若除牝牡骊黄论，只恐南人认亦难。"]},{"t":"题画","f":"七言绝句","c":["溪云十亩一瓜园，谁识山中此破轩。","伊吕巢由还认错，老怀天地共谁言。"]},{"t":"辛亥大寒梁塘道中有作 其一","f":"七言绝句","c":["春暖秋凉自不难，梅花何爱雪边看。","自知不及尧夫老，今日梁塘是大寒。"]},{"t":"辛亥大寒梁塘道中有作 其二","f":"七言绝句","c":["冻云江路本知难，山是山人分所看。","自裹木棉粗破衲，老夫何怕北风寒。"]},{"t":"乐道斋诗定山居士为彭世英书世英十过定山所得止此昔东坡鬻马方叔不免更鬻然于此纸世英岂待一过宿哉世英之戚必有此纸者尚亦知世英之不易得也","f":"七言绝句","c":["此妙人间各自真，天机流动静中春。","谁知庭草才拈后，犹有高谈隔壁人。"]},{"t":"题沈天趣梅花禽鸟卷","f":"七言绝句","c":["花鸟閒寻雪半枝，瘦筇拈到酒醒时。","莫言无极乾坤妙，只许濂溪一老知。"]},{"t":"琴鹤双清卷","f":"七言绝句","c":["一笑乾坤道眼馀，尽将琴鹤认鸢鱼。","老夫霅水昆山坐，莫道舟中妙不如。"]},{"t":"松风梅月为孤鹤翁作","f":"七言绝句","c":["云影天光拈仲晦，溪声山色舞东坡。","四千八万今如此，我问先生意若何。"]},{"t":"素庵为萧贵赞作","f":"七言绝句","c":["平生本质今如此，老去未能污一毫。","俯仰仲尼磨不磷，百年天地鬓萧骚。"]},{"t":"刘振之挽卷徐子仁题曰惜才","f":"七言绝句","c":["百年涂抹皆成学，吴郡徐霖正惜才。","安得不虚生死话，梦中呼起振之来。"]},{"t":"题画和韵","f":"七言绝句","c":["滚滚云山荡此身，不知何物更疏亲。","年来我问天峰阁，笑恐回头错应人。"]},{"t":"僧一庵","f":"七言绝句","c":["云在青天水在瓶，古僧何处说今僧。","一庵若问真何一，昨夜庵中火是灯。"]},{"t":"兰石","f":"七言绝句","c":["流水香风乱石中，随花傍柳与人同。","不知皇极书成否，莫问天津击壤翁。"]},{"t":"和张子如寻梅诗","f":"七言绝句","c":["梅花一笑有无间，消息徒将问定山。","是水是云皆是树，老夫驴背送君还。"]},{"t":"梅花 其一","f":"七言绝句","c":["江亭自笑读何书，此意乾坤忽有馀。","四十四年痴老病，梅花才见是鸢鱼。"]},{"t":"梅花 其二","f":"七言绝句","c":["天机谁与漏春痕，独写梅花到石根。","老子欲收元气坐，直从开阖看乾坤。"]},{"t":"题竹为五叔父作","f":"七言绝句","c":["多少金相玉质温，百年高节老乾坤。","凭谁欲把栽培问，个个清风是子孙。"]},{"t":"画马 其一","f":"七言绝句","c":["苜蓿空山恋肯肥，性龙骨马本相违。","古今分定庖羲眼，伯乐虽看认恐非。"]},{"t":"画马 其二","f":"七言绝句","c":["野草寒风捲雪乾，病躯斜阁瘦阑干。","相逢刍豆人间者，谁把行天步骤看。"]},{"t":"寄吴抚州 其一","f":"七言绝句","c":["深山忝窃旧相知，既别还胜未别时。","老梦秋来如不到，静中閒看浴云池。"]},{"t":"寄吴抚州 其二","f":"七言绝句","c":["万古人心万古真，续骚亭上续骚人。","閒来莫笑山中坐，不是前年活水春。"]},{"t":"寄吴抚州 其三","f":"七言绝句","c":["县桃台柏已无休，五马金溪亦细侯。","知我尚多狂妄意，有人大刻在黄州。"]},{"t":"和盛文元 其一","f":"七言绝句","c":["花鸟人间本自妍，相争出手肯徒然。","机心已与狂夫尽，不对棋枰二十年。"]},{"t":"和盛文元 其二","f":"七言绝句","c":["人间万事有渊源，六籍谁闻是出言。","画本不教花样乱，后来人说盛文元。"]},{"t":"寄祭酒林先生 其一","f":"七言绝句","c":["狂谬无端似病风，少年此处几人同。","如今万事消磨尽，甘做乾坤一病翁。"]},{"t":"寄祭酒林先生 其二","f":"七言绝句","c":["问简山林敢自迂，岂知霄汉与樵渔。","果看忘世真忘否，又写三山祭酒书。"]},{"t":"今年雨中盛文元又至","f":"七言绝句","c":["细雨疏篱晚菊边，茅斋又坐盛文元。","作诗写字閒无用，相与山中一醉眠。"]},{"t":"弘治三年秋七月喜雨有作 其一","f":"七言绝句","c":["一拜甘霖一滴春，山中念念几斯民。","往年记得填沟泪，犹有僧堂粥外人。"]},{"t":"弘治三年秋七月喜雨有作 其二","f":"七言绝句","c":["满放天瓢浩荡春，一年饭碗尽吾民。","如今万事无高眼，国虑天心到几人。"]},{"t":"弘治三年秋七月喜雨有作 其三","f":"七言绝句","c":["蓑笠焚香祝帝春，任人嘲笑是何民。","深山若有为霖者，肯作田头拜雨人。"]},{"t":"弘治三年秋七月喜雨有作 其四","f":"七言绝句","c":["旱到双泉也半春，四方还有桔槔民。","而今有饭家家饱，才满峰头活水人。"]},{"t":"画菜为杨黄门作 其一","f":"七言绝句","c":["人间何处觅虚空，曾点源头路未穷。","若把邵家楼阁看，士夫风味只涪翁。"]},{"t":"画菜为杨黄门作 其二","f":"七言绝句","c":["百可亭中虽自浅，千红堆里本非深。","南园若与前川别，不是乾坤万物心。"]},{"t":"客有妄解余笑恐回头错应人之句者用韵 其一","f":"七言绝句","c":["一发云何是一身，不知吾父是谁亲。","寒山莫把钟敲破，或有姑苏不睡人。"]},{"t":"客有妄解余笑恐回头错应人之句者用韵 其二","f":"七言绝句","c":["此人元本是天身，何物人间看不亲。","却笑南泉无大手，不知还有热瞒人。"]},{"t":"一山为张子如作","f":"七言绝句","c":["乾坤万物见非私，万古谁言不子思。","我却是山山是我，于今要与一山知。"]},{"t":"斗山杂诗","f":"七言绝句","c":["渔蓑烂舞钓船中，谁遣先生此梦同。","偶到南湖看月色，元来天地亦高风。"]},{"t":"禅者王福省号觉庵余不知禅何以应福省聊据已见塞白然乎否哉太虚老僧千眼观音当一照我 其一","f":"七言绝句","c":["莽将觉悟了心传，坐透鸢鱼自在天。","我亦鸢鱼中坐看，此身元是碧圆圆。"]},{"t":"禅者王福省号觉庵余不知禅何以应福省聊据已见塞白然乎否哉太虚老僧千眼观音当一照我 其二","f":"七言绝句","c":["一坐蒲团几百功，浑沦打破作圆通。","腐儒只欲泥君窍，万古仍收混沌中。"]},{"t":"挽诗","f":"七言绝句","c":["刚道生姜树上生，百年奄忽可须惊。","若知戌亥天还老，万里秋空月自明。"]},{"t":"严陵钓台","f":"七言绝句","c":["东汉云台迹已休，万年风节在羊裘。","西来定是桐江水，不与漳河一处流。"]},{"t":"传俸","f":"七言绝句","c":["袖手功名二十收，乾坤何处不公侯。","钓台昨夜因君舞，舞破蓑衣未肯休。"]},{"t":"跋山谷墨迹","f":"七言绝句","c":["老涪一笑古风天，宋雅堂堂二百年。","点尽白头山阁雨，为谁聊泊太湖船。"]},{"t":"植松为叶掌教作","f":"七言绝句","c":["欲效人间长养功，霜根数寸了春风。","何时肯作羲皇梦，送与浮云十八公。"]},{"t":"一松","f":"七言绝句","c":["英风伟格动高寒，一盖堂堂万古看。","养得茯苓天味别，我来丸作正心丹。"]},{"t":"挽人","f":"七言绝句","c":["世间白发不容见，善恶老天难与言。","未必张生真夭绝，请从周易论贞元。"]},{"t":"南安张太守评白沙诗集有请予折衷之言","f":"七言绝句","c":["风花醉点个中春，谁与痴人说梦频。","问我折衷张太守，而今我亦是痴人。"]},{"t":"瑞鹊为周六合作","f":"七言绝句","c":["白发青天一笑中，龟书龙马古今同。","凭谁说与周夫子，我亦人间卖兔翁。"]},{"t":"题竹","f":"七言绝句","c":["千溪鸾凤舞苍空，虚直分明是此中。","玉振许谁知万古，白头天下领清风。"]},{"t":"友兰为林处士作","f":"七言绝句","c":["天伴真香空谷里，老人刚好结深期。","回看桃李诸儿女，莫怪平生梦不知。"]},{"t":"题画","f":"七言绝句","c":["午鹄随春得化工，碧桃花缀牡丹红。","乾坤又把庖羲眼，分付先生半醉中。"]},{"t":"缉熙子为潘二教作","f":"七言绝句","c":["在我文王肯未如，天光元本透真虚。","老生更与提公案，静坐何须更读书。"]},{"t":"方山道中","f":"七言绝句","c":["万物此中元活脱，眼前何处不流行。","去年记得方山路，甘雨和风说大程。"]},{"t":"题陈瑞山水画","f":"七言绝句","c":["万里江山陈瑞画，白头开眼定山村。","谁人得与青天阔，独有孤帆岛树痕。"]},{"t":"作小车成何子完诸友有诗和之 其一","f":"七言绝句","c":["康节车儿且共閒，万花扶得几翁还。","定山也有飞云顶，不是罗浮别有山。"]},{"t":"作小车成何子完诸友有诗和之 其二","f":"七言绝句","c":["人间何处问忙閒，黑发天涯白发还。","认得玉台巾样好，先生须爱玉台山。"]},{"t":"种瓜","f":"七言绝句","c":["巧拙天心自不差，人间分付各生涯。","白头如此深山里，我不种瓜谁种瓜。"]},{"t":"题画","f":"七言绝句","c":["如此风云际会辰，丈夫谁肯负经纶。","我知茅屋深山者，多是人间老病人。"]},{"t":"题竹名曰石泉清节张司寇求","f":"七言绝句","c":["老凤虞周万古同，霜梢能事尽苍空。","谁知水石空山意，也到金声玉振中。"]},{"t":"游定山寺和司马提学","f":"七言绝句","c":["古邑天留众壑幽，小溪随步领真秋。","源头水到相忘处，也恋天光不肯流。"]},{"t":"泉上请司马赋诗","f":"七言绝句","c":["如斯山水客如斯，满眼鸢鱼活动时。","欲了相逢千古意，先生只索要吟诗。"]},{"t":"华亭张博父子持司马书来且有求教之说于其别也诗以送之 其一","f":"七言绝句","c":["乾坤一劄到何深，两夜梅花许卧林。","老我白头肝肺在，此心之外更无心。"]},{"t":"华亭张博父子持司马书来且有求教之说于其别也诗以送之 其二","f":"七言绝句","c":["古今父子蔡西山，君在西山父子间。","千古路头休认错，海涯风月看君还。"]},{"t":"古愚卷为白沙乃兄作","f":"七言绝句","c":["箪瓢许与静中春，万古天留此味真。","若道老兄甘起倒，石斋夫子是何人。"]},{"t":"可亭","f":"七言绝句","c":["谁将无可仲尼心，来向人间可处寻。","我亦欲凭无可可，古今天地共吾襟。"]},{"t":"梅花仙子和韵","f":"七言绝句","c":["梅花几点天心妙，太极濂溪认果真。","莫只花神惟只汝，先生今也是花神。"]},{"t":"月宫仙子和韵","f":"七言绝句","c":["山河影子无还有，玉兔嫦娥幻与真。","我欲虚空都打碎，老夫拄杖捷如神。"]},{"t":"游平湖南寺","f":"七言绝句","c":["绿阴撑入傍湖州，水作清深树作幽。","是画不知还是寺，晚峰斜日更登楼。"]},{"t":"寄寿州廖同府","f":"七言绝句","c":["家鸡到处不须争，醉点风花亦有情。","我见白头张汝弼，今年又在寿春城。"]},{"t":"答定山僧","f":"七言绝句","c":["山僧问我梅花妙，何事无诗只笑看。","万物本知梅一我，老夫今日对谁谈。"]},{"t":"梅花 其一","f":"七言绝句","c":["古今世态本无穷，只在千红万紫中。","他日肯将调鼎意，白头分付各春风。"]},{"t":"梅花 其二","f":"七言绝句","c":["看到梅花眼莫狂，梅花狂岂易商量。","而今莫把林逋笑，犹有林逋识暗香。"]},{"t":"梅花 其三","f":"七言绝句","c":["梅花明月写天机，写到无诗乃是诗。","若说无诗还错否，邵尧夫也不能知。"]},{"t":"梅花 其四","f":"七言绝句","c":["笑把梅花醉一歌，九方皋奈简斋何。","溪云老子糊涂甚，尽说庖羲一画多。"]},{"t":"折桂图","f":"七言绝句","c":["蟾宫何说到荒唐，和月连根句偶狂。","识得吾心真桂否，不劳扳折自天香。"]},{"t":"兰","f":"七言绝句","c":["猗兰楚楚各溪春，乱叶香风本自真。","莫道伏羲难再见，出门何处不同人。"]},{"t":"九老图","f":"七言绝句","c":["或弄瑶琴或酒壶，一人林下已难呼。","相逢莫问知几否，九老深山世亦无。"]},{"t":"挽傅昆乃翁","f":"七言绝句","c":["求诗长尽过江频，每向迂夫托老亲。","安得显扬成孝子，定山终且是他人。"]},{"t":"桂轩","f":"七言绝句","c":["几曲西阑月满轩，桂花香本压秋园。","此香若问来何处，分付诗人莫浪言。"]},{"t":"跋李宾之诗卷","f":"七言绝句","c":["此卷题来墨未乾，诗才如此古今难。","山翁肉眼何劳见，请与人间道眼看。"]},{"t":"病中","f":"七言绝句","c":["湛然长谓此心天，病里何来念百千。","不学老衰还自谴，谨当鞭策领伊川。"]},{"t":"和答许巡按枉顾定山韵 其一","f":"七言绝句","c":["老病心随去节高，百年双鬓未应凋。","閒来莫道山中眼，不见银河万里桥。"]},{"t":"和答许巡按枉顾定山韵 其二","f":"七言绝句","c":["多少风花滥此亭，白云流水正泠泠。","大观肯把蓬莱意，打作西山一片青。"]},{"t":"和答许巡按枉顾定山韵 其三","f":"七言绝句","c":["千古真逢一豸冠，青山何怪万人看。","可知襟抱明良地，元有乾坤一个宽。"]},{"t":"和答许巡按枉顾定山韵 其四","f":"七言绝句","c":["妙句何来一小亭，古弦清庙自泠泠。","老生欲和无天趣，只有西山数点青。"]},{"t":"和答许巡按枉顾定山韵 其五","f":"七言绝句","c":["何处朝冠与病冠，青山一笼荷同看。","也知不与行藏别，画得丘轲样子宽。"]},{"t":"和答许巡按枉顾定山韵 其六","f":"七言绝句","c":["秋家元气领谁高，霜里春无半叶凋。","笑把鹰鹯鸾凤想，拜公千拜拜溪桥。"]},{"t":"与柳嘉兴 其一","f":"七言绝句","c":["山水湖州看未休，嘉兴曾亦减湖州。","有怀诗在天峰阁，都只嘉湖两郡侯。"]},{"t":"与柳嘉兴 其二","f":"七言绝句","c":["鱼在深渊鸟在天，平湖几日对南川。","嘉兴老守真知我，说与离怀二十年。"]},{"t":"与柳嘉兴 其三","f":"七言绝句","c":["一滥春风北海樽，山麋游走愧难论。","若将魏野閒评我，魏野当年不出门。"]},{"t":"赠奚举人","f":"七言绝句","c":["归去云霞费几藤，家山容有未曾登。","一灯须了相传意，莫作人间应付僧。"]},{"t":"宜乐堂为文鉴主事作","f":"七言绝句","c":["一家留眼是经纶，三代乾坤只此春。","惭愧柁楼开卷子，西风閒送过淮人。"]},{"t":"送张地官且寿乃翁","f":"七言绝句","c":["皇极乾坤共此堂，人间何处看沧桑。","白头不误人人是，千古尧夫一炷香。"]},{"t":"题周敬叔菊花孤鹤出韵 其一","f":"七言绝句","c":["酒杯无语问江州，曾许渊明共唾刘。","倘更白头成晋史，老夫当拜数枝秋。"]},{"t":"题周敬叔菊花孤鹤出韵 其二","f":"七言绝句","c":["大方海水一江湖，天地那分越与吴。","莫笑几枝开眼错，分明画画是河图。"]},{"t":"题周敬叔菊花孤鹤出韵 其三","f":"七言绝句","c":["酒盏东篱欲领春，陶家霜月几精神。","眼前若把天机认，只恐先生亦未真。"]},{"t":"题周敬叔菊花孤鹤出韵 其四","f":"七言绝句","c":["阴静圈分动与阳，又将太极问周郎。","可知自是公家物，一本西风万朵黄。"]},{"t":"送太学生冠带还蜀 其一","f":"七言绝句","c":["圣世谁将老钓台，傍人行止莫相猜。","太平欲尽诗歌妙，须到山中静处来。"]},{"t":"送太学生冠带还蜀 其二","f":"七言绝句","c":["孔孟行藏只此心，病来今日且山林。","先生若问终身计，作养君恩正海深。"]},{"t":"败荷鹡鸰为文二作","f":"七言绝句","c":["万古岐周治亦隆，凤凰千仞几梧桐。","我知此日文家意，不在秋荷数鸟中。"]},{"t":"访人不遇 其一","f":"七言绝句","c":["问水寻山偶自行，瘦筇聊复尽吾情。","山禽不识贤东意，尽向花前管送迎。"]},{"t":"访人不遇 其二","f":"七言绝句","c":["徘徊屐齿久苍苔，漫把东君一笑猜。","老子但知人是我，看花明日又须来。"]},{"t":"访人不遇 其三","f":"七言绝句","c":["小车儿自傍花行，到处无人识姓名。","分付山童休拜我，先生不是邵先生。"]},{"t":"李黄门琼林燕归图 其一","f":"七言绝句","c":["宫袍随马舞春罗，柳色花香满御河。","欲了赓歌明日分，春风还奈此恩何。"]},{"t":"李黄门琼林燕归图 其二","f":"七言绝句","c":["老眼羞还此放开，东涂西抹也曾来。","如今扶汉输公在，只有桐江一钓台。"]},{"t":"过六峰问买田黄山 其一","f":"七言绝句","c":["卖犊年年得几钱，移家何处问安眠。","白头笑恐黄山尹，他日催租更卖田。"]},{"t":"过六峰问买田黄山 其二","f":"七言绝句","c":["鸡肋尊拳岂足供，一时何怪此元戎。","问田亦是痴人梦，天欲穷吾处处穷。"]},{"t":"歌风台","f":"七言绝句","c":["汉家猛将已成多，故里归来奈乐何。","安得贤臣思更切，大风千古一赓歌。"]},{"t":"张秋夜泊忆季升都宪时出巡兖州","f":"七言绝句","c":["孤舟旅泊果堪情，明月黄河水乱倾。","两夜老人浑不睡，别怀长恋兖州城。"]},{"t":"张秋 其一","f":"七言绝句","c":["神禹谁知自圣功，人间大智本无穷。","分流尽却漕夫伎，万古黄河水只东。"]},{"t":"杨青驿","f":"七言绝句","c":["杨柳青题旧驿亭，人来杨柳半凋零。","可知自有吾心柳，万古无穷一样青。"]},{"t":"题菜","f":"七言绝句","c":["风月人间有正传，一花一叶意无边。","数茎何自狂夫地，也梦濂溪太极圈。"]},{"t":"题竹","f":"七言绝句","c":["人间万事本无穷，都在金声玉振中。","老我平生空爱此，鬓毛萧飒满秋风。"]},{"t":"碧溪卷为张润之作","f":"七言绝句","c":["满镜秋风鬓不知，一囊天地一囊诗。","须眉莫把东坡百，了得人间一润之。"]},{"t":"菊花","f":"七言绝句","c":["霜枝几叶醉陶家，秋色南山也自佳。","千古无穷开老眼，岂徒太极是梅花。"]},{"t":"过张秋行台忆东山 其一","f":"七言绝句","c":["欲同何处许同论，著眼云泥老自昏。","留取行台高万丈，他年一笑醉龙门。"]},{"t":"过张秋行台忆东山 其二","f":"七言绝句","c":["天地刍荛自古今，訑訑千里岂公心。","可堪世路无穷态，搔尽行藏白发深。"]},{"t":"送程郎中弟致仕 其一","f":"七言绝句","c":["来谁具眼识行藏，归去青山策颇良。","多少京师誇不尽，圣君贤相在虞唐。"]},{"t":"送程郎中弟致仕 其二","f":"七言绝句","c":["小程天地是谁传，明道先生想更贤。","百尺竿头仍一步，莫将风月负伊川。"]},{"t":"题画 其一","f":"七言绝句","c":["清时许下钓鱼台，猿鹤深知苦怨猜。","万古行藏天与定，青山不久便归来。"]},{"t":"题画 其二","f":"七言绝句","c":["移家自约沈都台，阳羡青山更不猜。","七十二峰真可卧，梦中夜夜太湖来。"]},{"t":"题画 其三","f":"七言绝句","c":["何处青山不是山，天机活活水云间。","老夫高坐天峰阁，花里柴门自不关。"]},{"t":"题画 其四","f":"七言绝句","c":["千古迂狂此定山，更将何物老人间。","破瓢只也齑盐意，打透功名富贵关。"]},{"t":"题画 其五","f":"七言绝句","c":["万行烟柳万桃花，拍塞东风满意霞。","若论我家还似否，眼中不是是谁家。"]},{"t":"题画 其六","f":"七言绝句","c":["西泛东游兴欲狂，邵家春暖与秋凉。","四时老子俱堪出，绿树乾坤夏日长。"]},{"t":"题画 其七","f":"七言绝句","c":["千山木落眼全真，到处乾坤到处新。","安得清秋长万里，古今不见一毫尘。"]},{"t":"题画 其八","f":"七言绝句","c":["老眼江山处处新，雪中天地更精神。","人间岂识尧夫意，未有深冬未有春。"]},{"t":"题扇","f":"七言绝句","c":["秋风箧笥有炎凉，此道谁知白日光。","俯仰乾坤吾与尔，千年用舍一行藏。"]},{"t":"见贤堂见贤思齐之意也","f":"七言绝句","c":["客中一饱外何知，仍把诸公卷里诗。","老我不胜惊坐起，耳根华发正披披。"]},{"t":"授南京吏部郎中 其一","f":"七言绝句","c":["六十年来老倔强，也容白日簉鸳行。","京官体面知生涩，先遣庭趋拜侍郎。"]},{"t":"授南京吏部郎中 其二","f":"七言绝句","c":["一官老许向南京，遁卦同人万古情。","迂阔自知无一用，祗能开眼看升平。"]},{"t":"题画","f":"七言绝句","c":["平生老笔钟钦礼，细草奇花故故新。","安得此心吾再拜，静中常见自家春。"]},{"t":"梨云 其一","f":"七言绝句","c":["静无动有只狂夫，龙马乾坤各负图。","满眼梨云今几树，老禅刚道有还无。"]},{"t":"梨云 其二","f":"七言绝句","c":["人间道眼许谁分，禅伯中间我与君。","秋在满庭黄菊子，不知都可是梨云。"]},{"t":"梨云 其三","f":"七言绝句","c":["禅机何处与人同，泡影风灯一梦中。","如此白云如此树，不知何物可言空。"]},{"t":"梨云 其四","f":"七言绝句","c":["一笑冠巾万古同，莫将形迹到衰翁。","定知肯把梨云误，不负相留一月中。"]},{"t":"万柳庄","f":"七言绝句","c":["满怀天地隐疏帘，卷尽人间万柳檐。","安得风花无我处，江山随地醉陶潜。"]},{"t":"题邵国贤画 其一","f":"七言绝句","c":["瓜熟西园兔已窥，藤深叶暗子累累。","乾坤岂少宜瓜日，老子分明说与谁。"]},{"t":"题邵国贤画 其二","f":"七言绝句","c":["阴耦元归太极中，一圈天地妙无穷。","人人各有庖羲眼，莫向成都问老翁。"]},{"t":"寄罗洗马 其一","f":"七言绝句","c":["旧学相期祗自云，一言群议正纷纷。","白头看尽浮云过，明道先生果是君。"]},{"t":"寄罗洗马 其二","f":"七言绝句","c":["青天万事本无穷，巢许夔龙奈不同。","一笑肯容千古地，他年端庆有温公。"]},{"t":"答白沙","f":"七言绝句","c":["南海春风一古琴，天涯回首几知音。","野人未有钟期耳，只有钟期一寸心。"]},{"t":"题小仙画付小儿乙仝","f":"七言绝句","c":["道人何处领天机，都在吴仙手一挥。","千古乾坤千古梦，谁知鱼跃与鸢飞。"]},{"t":"题画 其一","f":"七言绝句","c":["天地颓然此秃翁，逢人何处托焦桐。","瘦筇短日柴荆外，万一山人不耳聋。"]},{"t":"题画 其二","f":"七言绝句","c":["东风笑弄野棠春，生意乾坤我亦人。","布袜青鞋春步远，小将诗句荅芳辰。"]},{"t":"春日郊行","f":"七言绝句","c":["春满江山桃李新，芳菲洗眼是何春。","大贤为政今如此，不道今人少古人。"]},{"t":"黄仙洞","f":"七言绝句","c":["溪有清流木有颠，朝来我饮夜来眠。","许由千古将巢父，信史无惭一路编。"]},{"t":"黄龙池","f":"七言绝句","c":["俯恨莺宫乘羽气，仰攀龙驭奏新题。","光明何处苍生眼，一角东南看白霓。"]},{"t":"上洪山顶","f":"七言绝句","c":["懒爱山僧不扫苔，前身我是德云来。","清虚看出诸天外，眼孔从今合大开。"]},{"t":"入洪山 其一","f":"七言绝句","c":["翩翩皂盖又青山，住世人还出世间。","万辙一途归去住，不应非禹不非颜。"]},{"t":"入洪山 其二","f":"七言绝句","c":["青春作伴入山来，花鸟平生不受猜。","割断红尘雄剑在，肯教腰下绣生苔。"]},{"t":"宿洪山寺","f":"七言绝句","c":["了了浑忘色与声，朝来谁梦复谁醒。","五根七窍休疑我，同向白牛车上行。"]},{"t":"白龙池","f":"七言绝句","c":["神龙妙用应天上，十雨五风时一吟。","能潜能跃公知否，影对寒湫笑不禁。"]},{"t":"登山 其一","f":"七言绝句","c":["千里桑麻压亩低，恩风德雨逐轮蹄。","富民侯印如天上，云是楼台风是梯。"]},{"t":"登山 其二","f":"七言绝句","c":["与报山灵太守来，山花山鸟亦迟回。","麻衣倘寄山中榻，肯对寒炉一画灰。"]},{"t":"息阴惠鱼乾","f":"七言绝句","c":["笋蕨腰镰委所穷，鱼盐分味忽烦公。","一毛不拔杨朱利，今古人情亦或同。"]},{"t":"刘媪送酒 其一","f":"七言绝句","c":["康衢声响罢陶陶，饥饿相寻到我曹。","美酝二升殊可恋，野人何事笑东皋。"]},{"t":"刘媪送酒 其二","f":"七言绝句","c":["谁将白鹤与青蚨，十五桥边卖酒垆。","赖是东邻刘老媪，一筒满眼不须沽。"]},{"t":"刘媪送酒 其三","f":"七言绝句","c":["襟颜何处不曾开，世短情多白发催。","一曲高歌还自听，青山笑覆白云杯。"]},{"t":"承嘉弟遣弟承规挈舟送客武昌舟还金矶适族弟承敬会矶下许相挽而上舟覆规与敬得拯规遂舍舟而归承嘉欲令规求舟止以诗","f":"七言绝句","c":["尔弟矶头真陆沉，茫茫不记此来心。","扁舟值得曾多少，天与平安抵万金。"]},{"t":"承颜弟书来有眼底流涎摇尾之叹诗以复之","f":"七言绝句","c":["商人门户几黄昏，云际疏星过雨痕。","赤脚大匡千丈雪，婆娑短褐半生温。"]},{"t":"画龙","f":"七言绝句","c":["作醢相逢信不虚，神灵应迓犬羊如。","普天霖雨当年寄，不到寒湫祗卧馀。"]},{"t":"画虎","f":"七言绝句","c":["短薄远山葵藿知，也教冯妇下车迟。","晓天一啸长风起，试问人间老画师。"]},{"t":"崧台别意卷为巴陵方氏","f":"七言绝句","c":["瘦马炎荒寄宦情，乌纱巾外野云青。","而今万里高秋兴，犹在三洲与七星。"]},{"t":"谢惠鱼","f":"七言绝句","c":["竹箩犯晓压肩低，枉辱鲜鳞色色齐。","冰雪有人烟浪里，几番昏晓不闻鸡。"]},{"t":"晓枕","f":"七言绝句","c":["风寻里裂几年衾，楼外梅花月色深。","流动春光都满眼，自将功业问成心。"]},{"t":"寄严先生罢任","f":"七言绝句","c":["纱帽閒眠背夕阳，几年歌里听沧浪。","夜来风雨宣城梦，千里蘼芜满地香。"]},{"t":"和沈大有国宾韵 其一","f":"七言绝句","c":["人间难记定难忘，眼底鱼潜共鸟翔。","开户一番飞动意，满檐春雨墨花香。"]},{"t":"和沈大有国宾韵 其二","f":"七言绝句","c":["戚里春光未易逢，朱门䆗窱杳难穷。","不多岐路驱驰里，无限珠玑咳唾中。"]},{"t":"花园四时词 其一","f":"七言绝句","c":["残山剩水也春光，何谢园池旧洛阳。","秉烛放歌天欲晓，雨香檐外更花香。"]},{"t":"花园四时词 其二","f":"七言绝句","c":["藤床兀兀己抛书，起倒无馀懒有馀。","花到蔷薇好报道，老头今亦为渠梳。"]},{"t":"花园四时词 其三","f":"七言绝句","c":["月亦停杯花亦停，又生恤纬后来情。","声横南徼千山马，势破西天万里鹰。"]},{"t":"花园四时词 其四","f":"七言绝句","c":["短褐人间无紫凤，连村□□足清波。","气含公鼎花神笑，影对寒崖十丈萝。"]},{"t":"次韵升卿弟 其一","f":"七言绝句","c":["拖犁蚤穗已成科，拾穗有人行且歌。","弋路自来还自去，今人心契古人多。"]},{"t":"次韵升卿弟 其二","f":"七言绝句","c":["泯泯日长人独坐，关关风静鸟同歌。","尘心生死全消未，天损分明不爱多。"]},{"t":"次韵升卿弟 其三","f":"七言绝句","c":["七尺自临潭底影，一瓢不聒树头风。","安心了了无言说，兴味都归半醉中。"]},{"t":"次韵升卿弟 其四","f":"七言绝句","c":["彼此衰荣并一空，夜来急雨战惊风。","午窗忽启初晴日，宇宙无端过眼中。"]},{"t":"鲁仲连","f":"七言绝句","c":["东海停波万顷馀，天行物化卷还舒。","一诬千载凭谁说，曾射聊城一纸书。"]},{"t":"画梅","f":"七言绝句","c":["铁桥曾识春风面，玉铉终和上帝亨。","散步江村霜月午，仙香万斛引丹青。"]},{"t":"偶题 其一","f":"七言绝句","c":["泉石清凉寄此身，市廛喧聒不闻人。","玄同自得今犹古，分别应惭我到君。"]},{"t":"偶题 其二","f":"七言绝句","c":["阿母棚中犬骨收，仰眠对语小詹头。","少将故事留诗活，不为儿孙骨相谋。"]},{"t":"桃林书屋为临江方文亨","f":"七言绝句","c":["片霞香点万书堆，手倦抛书拨篆灰。","多少旁人迷指顾，是天台不是天台。"]},{"t":"岳顶精舍为巴陵柳汝澜","f":"七言绝句","c":["坐久有人苔涩扉，颓然深处见天机。","午帏风启跏趺去，影在青天几翠微。"]},{"t":"寄沈大有 其一","f":"七言绝句","c":["水月相磨势两忘，千寻水月有蛟藏。","鄂城今夜思千里，一首书残一炷香。"]},{"t":"寄沈大有 其二","f":"七言绝句","c":["枕窍孤眠梦已忘，人间两手漫收藏。","祝融风满游人袖，一片崖兰万斛香。"]},{"t":"夜闻邻舟铃","f":"七言绝句","c":["阙足床旁折脚铛，全成人是我全成。","洞庭混沌清波耳，不聒人间昨夜铃。"]},{"t":"感昔","f":"七言绝句","c":["拗鬼纷更智已疲，鱼羹无复草根知。","只今回首金陵地，炰凤烹龙去合迟。"]},{"t":"寄喻祁阳子乾 其一","f":"七言绝句","c":["十丈青霓落语溪，茅茨移采午天低。","焚香闭阁君侯梦，千里烟霞路更西。"]},{"t":"寄喻祁阳子乾 其二","f":"七言绝句","c":["谩说鸦山与建溪，九疑仙谷露丛低。","轻黄脆绿香凝玉，坐醉中秋月影西。"]},{"t":"次韵喻祁阳子乾见赠 其一","f":"七言绝句","c":["拂几弹丝风满城，此刀千载砉然惊。","千寻一进竿头步，始信前贤畏后生。"]},{"t":"次韵喻祁阳子乾见赠 其二","f":"七言绝句","c":["竹绕官衙水绕城，帘前不到野人惊。","坐残水竹边头影，十丈婆娑月又生。"]},{"t":"次韵喻祁阳子乾见赠 其三","f":"七言绝句","c":["潇湘云雾锁丛林，玉色荷花许样深。","只恐尘巾看花眼，龙宫幽渺不知寻。"]},{"t":"次韵喻祁阳子乾见赠 其四","f":"七言绝句","c":["樵歌落日风满林，渔唱前湾夜气深。","此曲人间元不解，离鸾别鹤会相寻。"]},{"t":"次韵喻祁阳子乾见赠 其五","f":"七言绝句","c":["度十溪深更百溪，野云茅屋打头低。","云香莫遣闻猿鸟，逼得青鸾驾又西。"]},{"t":"次韵喻祁阳子乾见赠 其六","f":"七言绝句","c":["破笠不眠云在溪，两肩诗竦竹篷低。","波喧厉气风来北，山吐微光月出西。"]},{"t":"寄曾复初先生","f":"七言绝句","c":["草草当年启一音，洞庭东下笑鱼沉。","瘦筇拄破郴山雪，兴绕梅花独不禁。"]},{"t":"宜章再寄高挥使","f":"七言绝句","c":["小队貔貅影作双，云为伞盖柳为幢。","遥瞻万里元戎气，吞尽东南未肯降。"]},{"t":"阳溪图","f":"七言绝句","c":["溪北溪南着树遮，一溪风日一溪花。","君王莫遣丹青得，留与桃源一样誇。"]},{"t":"题梅","f":"七言绝句","c":["影落寒空月一痕，烟霞剩馥倩谁闻。","和羹欲试人间手，商鼎秋尘净几分。"]},{"t":"墨牡丹","f":"七言绝句","c":["本看魏紫与姚黄，开卷谁家澹墨光。","意思但知花一我，眼中色相已都忘。"]},{"t":"雨中陪沈仲律佥宪宿长芦用韵","f":"五言律诗","c":["孤帆兼日下，高树与秋迎。","天地真能大，江山各自清。","宦游吾马倦，尘梦此钟鸣。","默默同趺坐，谁知万古情。"]},{"t":"秋行","f":"五言律诗","c":["老夫携一杖，岸帻向林皋。","九月木将脱，千峰秋更高。","乾坤真寓舍，世事直秋毫。","我与巢由辈，真为莫逆交。"]},{"t":"忆舍弟","f":"五言律诗","c":["天边闻一雁，杳杳向南徂。","今夜西风冷，他乡小弟孤。","五人千里去，九月一书无。","欲作千行泪，凭谁寄客途。"]},{"t":"汎江和寿卿","f":"五言律诗","c":["放艇夫何意，天机忽远林。","川云元浩荡，鱼鸟自高深。","万里平生眼，三人此日心。","因思邵康节，终日打乖吟。"]},{"t":"次孤鹤老人观物亭坐雨 其一","f":"五言律诗","c":["江山通一雨，深似老夫清。","稍稍花全落，沉沉鼓未晴。","坐当新竹拜，睡起早霞明。","知我出门懒，连阴故有情。"]},{"t":"次孤鹤老人观物亭坐雨 其二","f":"五言律诗","c":["小阁题诗坐，高怀散远秋。","风花聊沈谢，行止自轲丘。","野暝微孤树，江清著数鸥。","与君真自厚，不是雨相留。"]},{"t":"送李德孚林缉熙还南海 其一","f":"五言律诗","c":["细雨桄榔树，清泉苦竹根。","先生旧家业，风日短篱门。","归计携诸友，迎舟立两孙。","能寻白沙子，同醉浊醪尊。"]},{"t":"送李德孚林缉熙还南海 其二","f":"五言律诗","c":["契合乾坤大，逢君胜白头。","江山如会意，天道此停舟。","久大贤人业，稀疏软布裘。","千峰不可见，明月在高楼。"]},{"t":"和容彦昭","f":"五言律诗","c":["世人无限事，南亩领农夫。","佳气山长在，秋江鹤自孤。","风流还我老，尘俗是君无。","朗月孤舟夜，能来共五湖。"]},{"t":"芝轩为江阴王景悦题","f":"五言律诗","c":["万古祯祥意，如今付此吟。","朝廷真极治，芝草又江阴。","薄雾千茎紫，微风众叶深。","商歌人共赏，谁复会予心。"]},{"t":"圣像寺","f":"五言律诗","c":["圣像移舟入，僧佳寺亦佳。","白云何处所，秋径此袈裟。","细雨怜棕叶，香风问橘花。","野人幽僻甚，随意宿烟霞。"]},{"t":"与孤鹤翁汎江","f":"五言律诗","c":["江晚真堪画，烟中树树清。","两人携小桨，万里荡秋溟。","醉眼岐周凤，虚名楚国萍。","西山知我意，个个矗银屏。"]},{"t":"雨中招廷信","f":"五言律诗","c":["往来频旧雨，今雨可相辞。","留取一尊酒，赏公千古诗。","风流真麈尾，跌荡更花枝。","自扫门前立，能来莫遣迟。"]},{"t":"答廷信","f":"五言律诗","c":["花鸟三年句，江楼坐不辞。","风骚真有此，老子是何诗。","印月深江水，盘空老铁枝。","君无怜俗眼，我已识君迟。"]},{"t":"送任生之","f":"五言律诗","c":["轩腾都治凤，淡寂祗冥鸿。","尊酒堪谁别，人心自古同。","行藏真此道，天地各深衷。","相对秋江上，芙蓉正晚红。"]},{"t":"寄奉吉水周先生 其一","f":"五言律诗","c":["十载师生义，千年父子恩。","投桃真可报，没齿岂须论。","白首沧江远，青天泰岳尊。","平生衣钵梦，长绕鉴湖村。"]},{"t":"寄奉吉水周先生 其二","f":"五言律诗","c":["几年仁水望，别恨不蹉跎。","一老应谁似，诸郎过我多。","春寻扶过子，酒醉舞东坡。","不得亲藜杖，其如感愧何。"]},{"t":"寄奉吉水周先生 其三","f":"五言律诗","c":["稽颡西江使，今年又手书。","先生真会面，弟子喜何如。","坐问犹消息，缄开数起居。","自怜鞭策远，痴钝老难除。"]},{"t":"寄奉吉水周先生 其四","f":"五言律诗","c":["一仕开曾许，当年本未能。","回头非自爱，多病果相仍。","把钓浑孤艇，摊书又几灯。","冰兢他日地，切恐误师承。"]},{"t":"重庆堂为何侍御作","f":"五言律诗","c":["食报无涯地，谁言我易论。","此心还日月，老眼自乾坤。","白发垂诸老，青云荡一门。","更知尧舜事，四海一君恩。"]},{"t":"寄掌教吴先生","f":"五言律诗","c":["三年怀此老，何处是衢州。","眼界真千里，空中正一楼。","人心周凤鸟，天道鲁春秋。","此意今谁领，空江自白头。"]},{"t":"藏书室","f":"五言律诗","c":["太上初寥寂，人文只可悲。","汗牛千卷是，注我六经谁。","日月开尼父，乾坤自伏羲。","病夫何所有，默坐定山痴。"]},{"t":"洗砚池","f":"五言律诗","c":["两在真难测，先生示此传。","浮云虽白日，本色自青天。","朱子方塘镜，濂溪太极圈。","此池吾亦有，观物草亭前。"]},{"t":"苍松轩","f":"五言律诗","c":["古今如此老，盖世几英豪。","草阁三千尺，苍龙五百条。","乾坤中独立，冰雪气难骄。","欲问平生业，撑天手正高。"]},{"t":"牡丹圃","f":"五言律诗","c":["玩物非吾事，聊观造化功。","春深三月后，公醉万花中。","蓓蕾先天妙，衣冠太古风。","此园虽独乐，还与众人同。"]},{"t":"门外柳","f":"五言律诗","c":["万物皆为我，开门柳忽深。","江湖閒坐处，天地此时心。","风月豪真在，箪瓢乐可寻。","元来程主簿，今古一閒吟。"]},{"t":"陇头云","f":"五言律诗","c":["阴偶为阳得，颓然只太虚。","偶观神妙处，一笑老横渠。","默默从升䧏，无无自卷舒。","青天横老眼，吾亦坐吾庐。"]},{"t":"绣衣记","f":"五言律诗","c":["六经元土苴，天地只微尘。","蜗篆曾谁笔，醯天偶自春。","我非文字眼，公殆屋乌人。","回也箪瓢乐，无言万古贫。"]},{"t":"太史铭","f":"五言律诗","c":["造化俄千古，文章便六经。","百年须我在，此石更谁凭。","英爽轩河朔，鸢鱼荡草亭。","乾坤留老手，著与太行青。"]},{"t":"得閒老人 其一","f":"五言律诗","c":["总总红尘是，匆匆白发皆。","不知何处里，乃有此翁来。","僧与看山得，江从钓月该。","莫言忙绝少，趁雨菊寻栽。"]},{"t":"得閒老人 其二","f":"五言律诗","c":["每将迂自哂，此老似还迂。","世上千年调，山中一卷书。","病长无扰扰，静只有如如。","老我青天眼，浮云看卷舒。"]},{"t":"得閒老人 其三","f":"五言律诗","c":["何处龙江叟，堪专水月盟。","众人皆此坐，天下与谁平。","不有终南病，能甘谷口耕。","题诗搔短鬓，老子不无情。"]},{"t":"遗爱为扬州刘同知作","f":"五言律诗","c":["扬州何处月，老去更江湖。","赤子千年戴，青天片石孤。","乾坤尧舜事，贤圣禹皋谟。","我问程夫子，浮云是有无。"]},{"t":"谢景瞻送蒲石","f":"五言律诗","c":["老子书斋可，虚明小弟成。","已交庭草翠，可少石蒲清。","拜受吾侪感，携擎此老情。","虚灵终藉服，岂但得长生。"]},{"t":"挽刘员外母","f":"五言律诗","c":["感激三年戴，悲伤万古图。","长江如可断，此泪亦须无。","何忝真员外，无成遂老夫。","哀歌云水地，病眼血流枯。"]},{"t":"寄新安宋同知","f":"五言律诗","c":["把臂华亭县，匆匆一语间。","㩳身频要路，回首独空山。","人与何年别，书曾几字还。","题诗无限意，分付菊花斑。"]},{"t":"承孙侍御枉顾失迓诗以谢之 其一","f":"五言律诗","c":["山岳真成动，柴门乃肯过。","看山虽我病，失接此心何。","感激青天望，留连白首歌。","可胜垂老意，舞破钓鱼蓑。"]},{"t":"承孙侍御枉顾失迓诗以谢之 其二","f":"五言律诗","c":["蛇鼠闻风窜，豺狼破胆愁。","巡行皆此老，当宁更何忧。","春每随流转，讴长管去留。","谁知定山子，诗略似春秋。"]},{"t":"鸢飞鱼跃亭与寿卿小酌 其一","f":"五言律诗","c":["酿熟麻姑酒，携来就树阴。","我狂能自恕，杯小不须斟。","溪水鱼同活，花丛鸟坐深。","此时如不饮，不是此时心。"]},{"t":"鸢飞鱼跃亭与寿卿小酌 其二","f":"五言律诗","c":["图凤苍天有，霜毛老鬓垂。","相逢真可笑，不饮欲何为。","拄杖公才出，壶觞仆屡随。","醉来虽只我，不记姓名谁。"]},{"t":"鸢飞鱼跃亭与寿卿小酌 其三","f":"五言律诗","c":["万事随天作，生涯半耳聋。","满斟今日酒，閒与寿卿同。","潦倒三杯后，氤氲半醉中。","夕阳花万朵，扶下小西峰。"]},{"t":"题画和沈豫轩","f":"五言律诗","c":["乾坤秋淡泊，万里见真空。","谁识此中趣，我怀无极翁。","江湖还野艇，今古各光风。","安得神游共，青天作主东。"]},{"t":"雨宿大潮寺","f":"五言律诗","c":["坐便山寺雨，更爱宿山中。","此壁孤灯影，何乡老病翁。","诗平容自考，静极与天通。","亦有蒲团债，吾儒但不空。"]},{"t":"浴香泉","f":"五言律诗","c":["老著天游步，江山不肯违。","春方玄酒淡，人每太初归。","是妙何言乐，无尘可振衣。","笑看曾点处，似或此狂非。"]},{"t":"臞庵","f":"五言律诗","c":["平生真面目，分付几峰烟。","病里歌惟凤，人间瓠亦天。","坎离吾药妙，山水尔藤贤。","醉盎还谁我，梧桐月满川。"]},{"t":"东原道中和大中","f":"五言律诗","c":["何处东涯路，乾坤醉眼空。","溪山吾老脚，日月此虚笼。","白帽天将近，芒鞋雪半通。","梅花消息好，还与问东风。"]},{"t":"香泉道中和大中","f":"五言律诗","c":["江山同一枕，何梦与神游。","紫气围黄鹤，青天坐白牛。","古今云汎汎，天地水浮浮。","莫道双凫外，王乔不可求。"]},{"t":"香泉和大中","f":"五言律诗","c":["老信风花脚，香泉又一来。","偶同贤辈浴，烂醉野人杯。","明月天无夜，光风路不埃。","行藏天地在，处处有高台。"]},{"t":"虹桥道中和大中","f":"五言律诗","c":["风光随阔步，处处眼俱新。","酒盏冬天趣，梅花句子春。","忘形幽壑几，把手白云频。","自笑閒潇洒，青天一幅巾。"]},{"t":"谢尚同以胙城尹谪重庆卫幕 其一","f":"五言律诗","c":["人才丁未榜，天地楚中英。","况有今巴蜀，宁知且胙城。","从吾惟子好，玉女是天成。","短发今浑白，题诗更几茎。"]},{"t":"谢尚同以胙城尹谪重庆卫幕 其二","f":"五言律诗","c":["远近迁难问，安危病不知。","书来空父执，老去见何时。","川蜀天非远，行藏道可疑。","长江千万里，滚滚是相思。"]},{"t":"赠丰城李士远用韵","f":"五言律诗","c":["白发今何去，来过亦此天。","子能留几日，吾且庆双泉。","世事云难定，青山雨结缘。","好看溪上月，还与共衰年。"]},{"t":"谢医士为谢汝申作","f":"五言律诗","c":["老向秋风几，长惊白发根。","何身无礼乐，此匕亦乾坤。","红杏谁家洞，山藤破屋门。","题诗从谢老，倒尽菊花樽。"]},{"t":"寄灵璧县博陆先生 其一","f":"五言律诗","c":["盖自云倾后，人间病各痴。","生涯贫不定，世故老堪疑。","扰扰终何益，堂堂肯自知。","好看相忆否，抖尽小囊诗。"]},{"t":"寄灵璧县博陆先生 其二","f":"五言律诗","c":["往日梭山老，三年梦欲猜。","交平千古定，天送一书来。","鱼鸟真堪约，溪云只老怀。","梅花堪寄否，惆怅钓鱼台。"]},{"t":"无锡游秦方伯池亭和韵","f":"五言律诗","c":["池亭天放手，都付浴沂翁。","此乐真谁得，狂夫亦偶同。","春游三月几，酒更万花中。","敢向鸢鱼眼，乾坤误主东。"]},{"t":"客至","f":"五言律诗","c":["野磬閒投止，寒山莫欲深。","醉留三日雨，狂了百年心。","云水青藜杖，乾坤老布衾。","蒙头閒不管，何处是晴阴。"]},{"t":"梅窗","f":"五言律诗","c":["草阁方虚坐，江空月色新。","乾坤还此夜，今古是何人。","稍稍宁辞晚，茫茫忽见春。","平生打乖意，今夜任天真。"]},{"t":"送毕都宪致仕","f":"五言律诗","c":["南国来何晚，龙门去未迟。","四方无事日，一老是閒时。","天地凭藜杖，风花任酒卮。","大臣终体国，去就不嫌疑。"]},{"t":"送严中书用韵","f":"五言律诗","c":["君随黄阁老，我爱定山泉。","廊庙才无忝，山林性只偏。","飞扬谁过分，行止岂无天。","肯作虚相爱，春江乱别弦。"]},{"t":"雪中和怀玉 其一","f":"五言律诗","c":["我意留公厚，苍天知此无。","朔风三日雪，清世两迂夫。","玄酒污樽礼，梅花太极图。","无言还对坐，何必论鹅湖。"]},{"t":"雪中和怀玉 其二","f":"五言律诗","c":["对坐无言处，无中更有无。","圣贤公自是，宇宙我非夫。","人世开天境，江村挂雪图。","此中凭打过，老眼送江湖。"]},{"t":"雪中和怀玉 其三","f":"五言律诗","c":["陈叟题诗去，江湖梦寐长。","主人惟老屋，夫子更匡床。","东鲁千年脉，南丰一瓣香。","可堪知己恨，残月管江方。"]},{"t":"雪中和怀玉 其四","f":"五言律诗","c":["天心何处问，默坐正寒更。","古调今疏越，天和此太羹。","夜深群动息，冬老一阳生。","料得梅花月，乾坤只么清。"]},{"t":"雪中和怀玉 其五","f":"五言律诗","c":["未尽孤撑力，风波却少回。","江湖今日好，天地此帆开。","水静天平阁，山苍雪漫排。","行藏应此老，真见仲尼来。"]},{"t":"梅花用韵","f":"五言律诗","c":["草亭天正阔，老眼又河图。","静坐千年后，谁知一画无。","鸢鱼还此老，天地本真吾。","不见庖牺氏，掀髯一笑孤。"]},{"t":"白马席间和白沙先生","f":"五言律诗","c":["万里何乡老，青天白帽来。","神仙在人世，随处是蓬莱。","云影千江月，天心数点梅。","平生夫子意，又许铸颜回。"]},{"t":"龙洞和白沙","f":"五言律诗","c":["何年留此洞，想见太初来。","风月谁张主，阴阳此荡开。","地灵真孔窍，元气古胚胎。","悟得庖牺意，狂歌月满台。"]},{"t":"浴香泉和白沙","f":"五言律诗","c":["我是白沙门，块然一顽铁。","仰视林缉熙，天地自悬绝。","感兹铸颜功，红炉一点雪。","何处浴沂归，吟弄香泉月。"]},{"t":"和白沙秋夜述怀 其一","f":"五言律诗","c":["此老真何意，我来更忆家。","西风聊短鬓，细雨只黄花。","慈母谁无老，京师也自佳。","玉台巾样好，戴著有人誇。"]},{"t":"和白沙秋夜述怀 其二","f":"五言律诗","c":["万里行藏意，先生不遣疏。","此心无系著，到处有鸢鱼。","白发看虽满，青山不受呼。","前年荔枝熟，童子报徵书。"]},{"t":"宇门承沈慎之任以庄送至句曲诗以道别","f":"五言律诗","c":["樱笋江南路，扁舟兴不孤。","仪形吾岂敢，风韵子真无。","水月歌潼渚，风花坐练湖。","乌头何足虑，老力更能扶。"]},{"t":"挽李仁贵大理母","f":"五言律诗","c":["万古坤宁意，人间又委形。","平生交白发，儿辈与沧溟。","南国人三代，西江女一经。","百年堪幻境，江冷各山青。"]},{"t":"喜闻谢元吉子咨领乡荐","f":"五言律诗","c":["万里湖南信，谁将到荜门。","此翁真有后，天道岂难论。","伯雨生何忝，元城死亦存。","何时堪慰藉，骑马下江村。"]},{"t":"同年蒋侍御枉顾和韵","f":"五言律诗","c":["古洞斜阳外，柴门得晚江。","桃花迷处所，骢马问何邦。","坐客茅亭几，歌诗稚子双。","鹿门虽爱我，我岂鹿门庞。"]},{"t":"中秋无月和廷信","f":"五言律诗","c":["乾坤今夜月，本色共青天。","纵有三更雨，能遮万古圆。","妖蟆徒自绝，顾兔岂谁怜。","老我浮云眼，寻常北斗边。"]},{"t":"十六夜晴月朗复用韵","f":"五言律诗","c":["此夜江边月，清光昨雨天。","自知虽小待，曾不减高圆。","以往复何闷，今看岂足怜。","老夫观否泰，起坐钓台边。"]},{"t":"徐光岳至 其一","f":"五言律诗","c":["江寺留诗夜，今年又八春。","溪山惟一我，肝肺更何人。","偶此来还否，相看梦与真。","白头无限意，分付月溪滨。"]},{"t":"徐光岳至 其二","f":"五言律诗","c":["江门千古地，来往有南川。","夫我何为者，相过亦此贤。","水花无别趣，庭草有真传。","活水亭前月，能留共老年。"]},{"t":"活水亭赠光岳","f":"五言律诗","c":["活水如斯活，佳山更莽佳。","已留庄叟坐，也直寿卿来。","拄杖随行老，风花信口开。","百年寻乐处，须子得吾怀。"]},{"t":"月溪雨后同东川光岳二徐贤叔侄坐鸢飞鱼跃草亭","f":"五言律诗","c":["此亭谁谓好，最好夕阳时。","老我三人意，黄鹂两个知。","花枝摇太极，云影荡玻瓈。","遂以天机妙，匆匆著小诗。"]},{"t":"同东川诸友溪上晚钓 其一","f":"五言律诗","c":["诸老斜阳外，长竿共把时。","雨深花倒醮，溪晚钓频移。","圣代渔翁我，人间此乐谁。","醉来溪上舞，老鬓白披披。"]},{"t":"同东川诸友溪上晚钓 其二","f":"五言律诗","c":["潦倒青溪上，閒随放宕缘。","请谁留白日，任我钓青天。","酒舞长蓑烂，花簪破笠圆。","醉归扶不远，家只小东烟。"]},{"t":"溪上和光岳","f":"五言律诗","c":["几点庖羲画，风花数子寻。","茫茫人物我，滚滚去来今。","杖履平生事，溪山此日心。","更看扶老步，云水几峰深。"]},{"t":"西峰和光岳","f":"五言律诗","c":["天下閒人几，青山一短筇。","莫言知我少，还有白沙同。","南海五千里，罗浮四百峰。","白头云水地，飞动意无穷。"]},{"t":"活水亭和东川","f":"五言律诗","c":["莽莽鳌峰子，区区活水村。","百年真眼孔，一个小乾坤。","几榻诸公下，吾家万古存。","与君风月处，刚对白沙樽。"]},{"t":"宿伯显家","f":"五言律诗","c":["平生安老睡，此夜独何期。","病枕风谁碍，疏棂叶放欺。","山留人愈静，月有句专奇。","若许论更鼓，因知某亦知。"]},{"t":"将往平湖寄白沙","f":"五言律诗","c":["石翁何处是，何处石翁心。","南海梦长到，平湖别亦深。","桨移花在荡，瓢饮月同斟。","明日南川至，相思各苦吟。"]},{"t":"送吴明府献臣","f":"五言律诗","c":["门前何处客，问是广东船。","行止虽殊路，江山共一天。","閒随花意思，老结酒因缘。","未了茅根念，天峰望子旋。"]},{"t":"寿边处士","f":"五言律诗","c":["野日苍峰路，青天一布巾。","莺花真老计，天地此遗民。","海瓮仙醅熟，仙居帝画真。","白头今太古，公外更何人。"]},{"t":"王审理封赠卷 其一","f":"五言律诗","c":["岁月青山在，春风短发前。","乾坤遗此老，儿子定吾天。","破衲存深计，秋藤结老缘。","封章天与在，终亦到林泉。"]},{"t":"王审理封赠卷 其二","f":"五言律诗","c":["此日三迁教，何惭丌氏前。","筑埋虽恶地，贤孝果青天。","万事慈中分，封书意外缘。","我当贤母墓，酌以定山泉。"]},{"t":"德州","f":"五言律诗","c":["两月京师路，今来尚一千。","虚名非雅事，薄计只苍天。","夜泊随孤驿，鸡声各放船。","小诗留一雨，又了德州缘。"]},{"t":"与国贤和西涯","f":"五言律诗","c":["人间文字眼，千古得吾师。","山馆深留夜，京师在见时。","虚名吾道在，垂老瓣香迟。","静坐忘言妙，终身是此期。"]},{"t":"荣庆堂","f":"五言律诗","c":["诏书新命下，老子况真贤。","岁事匆匆日，人间活活天。","老无非分福，生有圣贤缘。","万古春秋在，题诗肯自偏。"]},{"t":"和白沙韵","f":"五言律诗","c":["一老真南海，乾坤此定交。","花深长自爱，根好不须浇。","云水天无极，江山月满瓢。","可人今在眼，何意欲相招。"]},{"t":"挽人","f":"五言律诗","c":["浮云成惨戚，天地动哀吟。","白鹤江山泪，孤儿父母心。","百年恩自切，天意报还深。","万古封章在，穷碑倚墓阴。"]},{"t":"挽人","f":"五言律诗","c":["人生庄叟癖，死乐果谁传。","此固虽虚诞，何凭更惘然。","乾坤都父母，今古几亲贤。","一洒乌台泪，人间肯自偏。"]},{"t":"宿寒山寺用韵寄文太仆","f":"五言律诗","c":["位此天何说，才今道所然。","相逢浑旧雨，此别更青天。","周邵平生契，江湖白发缘。","不朦僧寺月，惆怅过江船。"]},{"t":"张明府惠伞","f":"五言律诗","c":["皇天迓不雨，青盖领初阴。","畎浍枯遮看，岩泉脉引寻。","此时须大厦，何处不流金。","一卷蓑衣薄，云生枫树林。"]},{"t":"病暑","f":"五言律诗","c":["暑无今岁剧，病甚往年侵。","月瘦频池曲，风微空树阴。","飞情霄汉健，潜意泳游深。","道暍人人是，金卮恐乏斟。"]},{"t":"用韵寄李公冶","f":"五言律诗","c":["倚遍东楼柱，孤吟暝色侵。","人情限一舍，天道伏群阴。","黍熟黄鸡在，人閒白屋深。","家慈愧吾子，交酒两回斟。"]},{"t":"和周宪长时可留别 其一","f":"五言律诗","c":["青青阶下草，生意又逢君。","往古春馀几，而今始属人。","看看涵宇宙，兀兀断知闻。","不注图书脚，探玄笑子云。"]},{"t":"和周宪长时可留别 其二","f":"五言律诗","c":["千古韶音歇，一声何处讴。","华堂人半醉，红烛影交流。","象纬罗天阙，云霓护客舟。","楚江黄鹤唳，清梦亦高楼。"]},{"t":"和周宪长时可留别 其三","f":"五言律诗","c":["身著紫藤蓑，门掩碧烟萝。","辟人甘鸟兽，行路愧丘轲。","长醉兼长舞，一丘还一窝。","紫虚率道士，许我日相过。"]},{"t":"和广西吴宪副 其一","f":"五言律诗","c":["我本楚狂人，荆州此识君。","云山还昨梦，世路与人分。","短褐曾嫌丑，虚名自愧闻。","兼金数字至，高义激浮云。"]},{"t":"和广西吴宪副 其二","f":"五言律诗","c":["无民不清静，有吏与歌讴。","古调何人会，明公是此流。","长风破巨浪，孤影落虚舟。","独倚阑干月，几回明远楼。"]},{"t":"和广西吴宪副 其三","f":"五言律诗","c":["绣斧昭州路，并茗透密萝。","阴符兼老子，剑术陋荆轲。","竹护新氓舍，烟消旧獠窝。","倘馀经略此，不惜重经过。"]},{"t":"与南海陈秉常容彦昭宿新江书院","f":"七言律诗","c":["万里高人万里航，迟回今日更江乡。","湖山几处延佳赏，天地三人会此堂。","白鸟青天谁眼界，清风明月我藜床。","道人拜约重来此，留与今朝一瓣香。"]},{"t":"清江别业","f":"七言律诗","c":["茅屋江村映白沙，百年此地是生涯。","雨香花气浑三月，暖日和风自一家。","邻里相邀同社酒，门人候出御牛车。","此中多少悠然意，开眼青山个个佳。"]},{"t":"寿徐母","f":"七言律诗","c":["老去流年祇暗惊，一生心胆解谁倾。","青裙白发终无恙，老眼皇天亦自明。","旧业此身真不阻，纲常万古恐非轻。","薰风六月榴花酒，谢得邻姬感嘅情。"]},{"t":"陪南川浴香淋泉","f":"七言律诗","c":["下马清泉坐两翁，风光随处与人同。","百年尽放三杯里，万象同归一洗中。","土屋背墙烘野日，午溪随步领和风。","儿童拍手休相笑，此日狂夫兴颇浓。"]},{"t":"寄万廷器","f":"七言律诗","c":["乾坤此日聊携卷，文字当年略滥觞。","玉树偶惊吾眼在，菊花相对酒杯长。","山林放手招明月，江海归帆挂夕阳。","明日老痴如问讯，欲将秋思托潘郎。"]},{"t":"游灵岩山","f":"七言律诗","c":["百年未了青藜杖，又向灵岩坐晚晴。","我与白云同自在，月交秋夜极分明。","青天旷野真能大，白鸟沧江本自清。","俯仰峥嵘男子事，肯将容易负平生。"]},{"t":"汎江和徐寿卿","f":"七言律诗","c":["风光满眼欲无边，老子心情亦浩然。","晚日行行飞白鸟，小舟个个泛青天。","谁能此地真无碍，我与青山似有缘。","几欲奉身思乞退，不知明主肯哀怜。"]},{"t":"游琅琊寺 其一","f":"七言律诗","c":["窅然天地岂人寰，紫翠无穷十里间。","閒看古松寻坐石，偶随流水入深山。","四时花在岩岩好，何物僧来个个閒。","我有新诗三百首，苍岩题遍不知还。"]},{"t":"观龙泉寺泉","f":"七言律诗","c":["一泓泻此下烟萝，坐我幽深古涧阿。","树霭散分千太极，镜光摇动百东坡。","云天荡漾看时满，风月招邀坐处多。","岩畔有人如会意，数声全是濯缨歌。"]},{"t":"观庄严寺大树","f":"七言律诗","c":["杏坛风雨有桓魋，此树能容老翠微。","梦里几番全是幻，人间万事果谁非。","繁阴蔽日三千界，黛色参天五十围。","我欲南堂借斤斧，不胜三匝绕斜晖。"]},{"t":"承马侍御过访 其一","f":"七言律诗","c":["清江大树老夫家，只许衡门管岁华。","云谷有诗皆感寓，柴桑无酒不黄花。","百年事业长镵老，万里风云醉眼赊。","何处西台贤御史，也来垂眼钓鱼槎。"]},{"t":"承马侍御过访 其二","f":"七言律诗","c":["江天万里一贫家，此老能来共物华。","到处小滩横钓艇，我家明月照梅花。","山中野鹿元相伴，江上清风不用赊。","拾得支机遗石否，年年星汉望仙槎。"]},{"t":"承杨侍御枉顾","f":"七言律诗","c":["江头深树草堂孤，故旧诸公过此无。","小吏忽来传子到，老夫虽病遣儿扶。","绣衣御史青骢马，田舍翁家浊酒壶。","肯为交欢拚一醉，莫嫌礼貌老农粗。"]},{"t":"送刘同府之柳州文介公裔也","f":"七言律诗","c":["天将明月与江村，许我狂歌阁酒尊。","人物已拚眵□眼，此髯谁使到吾门。","鄙人何敢当贤友，文介须应出此孙。","莫怪剧谈留更住，瘴江回望合清魂。"]},{"t":"送吾掌教子还开化","f":"七言律诗","c":["爱此娟娟玉树柯，眼中今日更须多。","人才江浙堪吾氏，文字苏家又小坡。","诗卷袖寒携海岳，夜船江稳坐星河。","英年自古多难料，此后轩腾奈尔何。"]},{"t":"疟起偶作","f":"七言律诗","c":["几随藜杖起方床，肯信吾乡似瘴乡。","百计可谁驱疟鬼，三年以命托槟榔。","山随病起青逾峻，菊到秋深瘦亦香。","宽尽寒衣谁敢怨，诗书为祟是寻常。"]},{"t":"采石","f":"七言律诗","c":["落日孤舟进此村，北风浪浪打山根。","忠臣万古虞公庙，诗鬼千年太白魂。","旧垒不知何世代，长江曾战几乾坤。","风沙眯尽登临眼，只有长安望不昏。"]},{"t":"灵岩山逢大虚僧","f":"七言律诗","c":["云水秋江与别踪，三年不见意何穷。","谁知小榻青灯里，又是寒岩白发中。","坐久可忘今夜月，梦回谁唤此堂钟。","相逢更有梅花约，留取他年一笑同。"]},{"t":"香山九老图","f":"七言律诗","c":["山林我极劳千虑，宦海谁能着万牛。","自古更无陶靖节，而今须□白江州。","寻常此日才多病，八十他年更几秋。","俯仰乾坤无一语，道人乘月坐江楼。"]},{"t":"荣庆堂为大理作","f":"七言律诗","c":["万古明良分付定，早从尧禹到如今。","小臣肝胆天堪照，圣世恩波海未深。","紫极逶迤春荡荡，天风寥廓路骎骎。","沧江回首多迂病，愧尽贤人用世心。"]},{"t":"送张廷玉司训河南","f":"七言律诗","c":["自从尼父一伤麟，斯道传来恐未真。","更识老天当此日，肯将木铎与何人。","师门万古真堪柱，檀杏千年也自春。","到此精神须会领，莫教铜狄笑人频。"]},{"t":"泰山和通伯侍御 其一","f":"七言律诗","c":["极为东南镇此寰，岩岩气象许谁攀。","九天日月摩千古，万里华夷镇一山。","培塿众形从起伏，乾坤此老自安閒。","也知开辟从真宰，领得中原正气还。"]},{"t":"泰山和通伯侍御 其二","f":"七言律诗","c":["万象同归造化门，含弘光大总无痕。","中原有子谁轻鲁，厚德何人不仰坤。","绝顶最高惟日见，阴岩极下有雷奔。","诸公肯作寻常看，自古山存道亦存。"]},{"t":"挽周景明父旧曾请余铭墓","f":"七言律诗","c":["中郎有道非吾汝，石尾何由亦贱名。","大手谁家无愧色，善人此老或平生。","百年可考诸儿子，千古何穷一墓铭。","曾过苍峰竹山路，白云真个满佳城。"]},{"t":"云潭为周文都作","f":"七言律诗","c":["天地斯文元未老，百年曾到岭南无。","偶观陈子云潭记，便是濂溪太极图。","龙马龟书千古在，青天北斗几星孤。","凭君着我西窗眼，卖免人间或老夫。"]},{"t":"拾地耳","f":"七言律诗","c":["野老贫无分外求，每将地耳作珍羞。","山晴老仆还堪拾，客到明朝更可留。","人世百年閒自乐，山斋一饭饱还休。","曲肱偶得同疏食，不是乾坤又孔丘。"]},{"t":"重阳杂兴 其一","f":"七言律诗","c":["柴门两月闭苍苔，老病何人得好怀。","短发乱从头上白，重阳偏是雨中来。","黄精瘦地锄空把，北斗沧江首正回。","赖有黄花知老子，东篱深傍酒杯开。"]},{"t":"重阳杂兴 其二","f":"七言律诗","c":["醉倒江头枕石眠，清风刚洒竹门边。","蚤闻世计皆春梦，肯放江花送老年。","凤鸟河图皇极理，西江南海钓鱼船。","狂歌急起披衣坐，今夜梧桐月倍圆。"]},{"t":"卧林亭杂诗 其一","f":"七言律诗","c":["雨里青山真可爱，此怀可许托张袁。","谁教老竹刚三个，独与痴人共一轩。","蹇浅谩劳吾子爱，迂疏敢顾众人言。","吾公满壁淋浪墨，何日来看独乐园。"]},{"t":"卧林亭杂诗 其二","f":"七言律诗","c":["尘埃满眼君东海，明月高楼每见之。","几载别离今酒共，两人肝肺此灯知。","支离万事何如我，潦倒千年却与谁。","伍月孤舟还问路，老怀甘与水东随。"]},{"t":"和陈允崇登定山","f":"七言律诗","c":["万里风光散远林，晚峰羸马正千寻。","手中日月丸天地，眼底风云变古今。","几笔化工山水趣，五经尼父圣贤心。","可堪白首犹多病，老凤西周意自深。"]},{"t":"南川至","f":"七言律诗","c":["老我天行云卧处，白沙消息又南川。","也知风月无边者，合与鸢鱼自在天。","世计东游西泛酒，天心南去北来船。","卧林更有明朝兴，多少神仙一处眠。"]},{"t":"魏尔瞻以濮阳璚之言请予写碑","f":"七言律诗","c":["南安太守老东坡，天下能书孰敢过。","万里不能携卷去，人间将奈此碑何。","君图茅绍名还久，我笑丰干舌最多。","明日肯随陈太史，墨花台上墨花歌。"]},{"t":"舍弟为予作一轩以为读书之所既落成诸友来贺作此诗歌以奉客 其一","f":"七言律诗","c":["千古风花弄酒卮，乾坤许我一茅茨。","吾斋洒落今如此，老子心情自可知。","小弟放歌兄亦舞，主人能劝客休辞。","去年有此今年好，又得江门数首诗。"]},{"t":"舍弟为予作一轩以为读书之所既落成诸友来贺作此诗歌以奉客 其二","f":"七言律诗","c":["容膝今年办小斋，数椽高傍读书台。","公看土屋休相笑，我老农夫分只该。","花为客来还起舞，燕知人好亦飞来。","兄酬弟劝从今日，一日须倾一百杯。"]},{"t":"赠湘阴夏进士","f":"七言律诗","c":["何处湘阴是所思，江篱刚有十年诗。","忽然草阁寒江上，飞下青天玉树枝。","故旧偶逢如未识，病躯留坐不知疲。","相看细数诸朋旧，祗我山中白发披。"]},{"t":"都隐为包春官作","f":"七言律诗","c":["胸中皆马未皆痴，雪里芭蕉始画师。","到处鸢鱼真活动，人间影响莫相疑。","须还禹稷忧勤处，便是巢由放浪时。","此意老夫知万一，老夫今日想君知。"]},{"t":"挽金川张公赞","f":"七言律诗","c":["将诗长与洞庭争，奇气胸中老未平。","梦里青山空有债，人间白发苦无情。","百年万事了不了，四十八年生未生。","我欲为君歌一曲，水寒江冷月三更。"]},{"t":"挽南昌刘氏双节","f":"七言律诗","c":["苦节收来烜古今，百年当日为谁深。","须还妇女无穷计，亦是人间本分心。","冯道胡为千古唾，刘家却此两真金。","我知东白文章泪，铁石人看亦满襟。"]},{"t":"栽树 其一","f":"七言律诗","c":["一径梅花一径桃，东风移得满山坳。","肯愁明日灵根萎，自有贫家活水浇。","着眼风光皆此意，醉人春色自吾醪。","白头笑尔青藜杖，一日烦君更几遭。"]},{"t":"栽树 其二","f":"七言律诗","c":["送得春光活水洼，大梨红杏更梅花。","和风甘雨来何处，万紫千红在我家。","好处天开花洞府，老来人作酒生涯。","眼前浩荡真如此，那得尧夫不自誇。"]},{"t":"栽树 其三","f":"七言律诗","c":["桄榔杖不妒春晴，扶我南园自在行。","二月半多春富贵，万花中一老先生。","百年何幸长康健，自古难逢是太平。","安得可人吴御史，一壶春酒共啼莺。"]},{"t":"寄李少参","f":"七言律诗","c":["风花水月满江湄，到处閒将拄杖随。","何处老翁携小艇，也随风汉醉蛾眉。","流行大块天如此，落魄古今吾似谁。","何日更同长笛去，曲栏横倚大江吹。"]},{"t":"早禾为官马食践殆尽","f":"七言律诗","c":["山田几月全无雨，抱瓮安能坐老夫。","粥食已安今岁减，马群谁遣一禾无。","眼昏口燥真欺得，天远山深可用呼。","且直区区馀事里，坐携书卷看河图。"]},{"t":"城市山林","f":"七言律诗","c":["青山何赖点红尘，此语无稽更觉新。","夫子不须频说梦，老生元本是痴人。","何谁不信鱼非我，道眼分明俗是真。","我亦有家城郭里，闭门长坐定山春。"]},{"t":"答孝感张都宪","f":"七言律诗","c":["静坐一丸閒弄处，都台拜问有诗无。","百年此道谁知己，今日王公下匹夫。","元气一时回宇宙，虹光千古照江湖。","下风欲作门前拜，老病支筇不可扶。"]},{"t":"送人出守姚安 其一","f":"七言律诗","c":["五月山中忧旱坐，送人作郡岂农夫。","寇恂黄霸真公许，桀溺长沮是我无。","行止此天元自定，知愚吾道果安图。","眼中若总姚安政，甘与元经送五湖。"]},{"t":"送人出守姚安 其二","f":"七言律诗","c":["乾坤剧许此肩担，五马今年走瘴岚。","此老朝廷何可去，南方民命亦须堪。","百年西蜀谁张咏，自古潭州也晦庵。","王道宽平君识否，当时孔孟岂迂谈。"]},{"t":"留秦用中","f":"七言律诗","c":["世故驱人百未休，江山何地可堪留。","乾坤此日还重九，风雨今年又一秋。","碧树可惊游子梦，黄花偏爱老人头。","且须急把东篱酒，回首江天独倚楼。"]},{"t":"送别秦用中","f":"七言律诗","c":["欲来消息满江湄，果见堂堂小仆随。","几夜好诗全压我，百年老眼更看谁。","宋唐大手诸公在，日月群经自古垂。","回首梧桐孤凤远，东南天阔海西陲。"]},{"t":"题项羽庙","f":"七言律诗","c":["一从天命舍歌讴，龙战中原苦未休。","天地我能悲楚汉，古今谁敢罪商周。","英雄可庙人千古，赤子何辜血九州。","惟有长江知我意，对人无语只东流。"]},{"t":"奉和蒋侍御见忆之作","f":"七言律诗","c":["万里乾坤任所之，风花指点过江时。","百年何处非沂水，老脚今朝又武夷。","两手正堪天靶柄，一家刚了圣藩篱。","凭谁唤起朱元晦，把酒长歌感寓诗。"]},{"t":"余生来自陜西求文谢其医师程文进将行诗以送之","f":"七言律诗","c":["蹇驴何处自关西，药裹新安手更携。","天下果谁知李昶，眼中须子爱丹溪。","古今王道医非缓，文字山林世颇低。","别去有丹怜老病，白头书礼候封题。"]},{"t":"寄新安周朝美司训","f":"七言律诗","c":["十年聋坐静修龛，倾耳江边一夜谈。","鞭策有情君自厚，驽骀无力我何堪。","菁莪梦里儿童感，云水天涯老病甘。","何日鸢鱼携手地，天机流动白沙庵。"]},{"t":"夏汝明持留鹤翁送行诗求和","f":"七言律诗","c":["圈点江峰一语深，十年分付几登临。","浮生日月浮生梦，太古乾坤太古音。","一枕烟霞聊我鼾，满川花柳是谁心。","与公笑把明朝事，共倚栏干酒一斟。"]},{"t":"和云东逸叟画花","f":"七言律诗","c":["乾坤一画本谁无，看到羲爻看禹谟。","何处梅花非太极，眼中龙马又河图。","有形万物皆堪我，无水人间不可湖。","多少天机言不尽，花枝今夜鸟频呼。"]},{"t":"挽刘衢州","f":"七言律诗","c":["梦走滁峰若个深，衢州何许到沾襟。","留连此道千年付，感激儿童片语心。","驽马正须资控勒，麒麟犹爱锁黄金。","白头硬寨何时已，落日悲歌下晚岑。"]},{"t":"南川书来知领平湖教官 其一","f":"七言律诗","c":["乾坤到处有知音，何自千峰又古琴。","世外浮名真腐鼠，人间木铎有天心。","百年道大吾何病，自古官卑职易任。","欲采芙蓉何处寄，空江十月水犹深。"]},{"t":"南川书来知领平湖教官 其二","f":"七言律诗","c":["朝阳倾耳凤凰音，此日虞廷有舜琴。","贤圣一时通治道，先生万古管人心。","浮沉在我先难断，花柳随时老更任。","且放平湖閒酒盏，千红万紫看春深。"]},{"t":"南川书来知领平湖教官 其三","f":"七言律诗","c":["满耳虞周治世音，平湖分与杏坛琴。","好凭烟月千年手，弹出英雄万古心。","岁月虚名双鬓改，乾坤大担老肩任。","白头多少江门意，海上青山个个深。"]},{"t":"南川书来知领平湖教官 其四","f":"七言律诗","c":["何许书来遗好音，春风刚坐草堂琴。","青天白日凭谁眼，流水行云得我心。","弄枕箕山真有许，钓鳌东海久无任。","先生自与行藏熟，不悔深山入未深。"]},{"t":"南川书来知领平湖教官 其五","f":"七言律诗","c":["太古乾坤太古音，不弹今日乃公琴。","病中我有痴聋耳，天下人无各自心。","轩冕云山难错料，千钧一羽果谁任。","酒杯何日平湖共，舞到梧桐月影深。"]},{"t":"南川书来知领平湖教官 其六","f":"七言律诗","c":["归装频送棹歌音，还把南川去日琴。","十载几谈周易卦，一官方是揽山心。","吉凶悔吝平生准，用舍行藏老力任。","每忆秋江临别话，一年惆怅钓台深。"]},{"t":"乙已元日","f":"七言律诗","c":["东风造次满江涯，花鸟无穷眼又开。","病痛百千馀种在，先生四十九年来。","古今到我真无谓，贤圣如天岂易阶。","欲与春光共流转，一丸閒坐读书斋。"]},{"t":"梁都事焚黄卷","f":"七言律诗","c":["展转平生罔极恩，光荣何念不乾坤。","蠹鱼白首虽经笥，黄纸青山果墓门。","富贵许人生死到，孝慈为分古今存。","山斋可到题诗意，大舜曾参欲与论。"]},{"t":"花严山","f":"七言律诗","c":["乾坤忽此是何方，风景居然不可当。","鸡犬几家仙洞府，烟云一幅米元章。","平生眼界何容易，老去行藏费主张。","箕颖料知难过此，巢由何敢负虞唐。"]},{"t":"过仙踪和光岳","f":"七言律诗","c":["潦倒烟云任不羁，乾坤随我放颠痴。","每从问寺寻僧处，点出随花傍柳诗。","拄杖每行真老仆，青山到处是相知。","白头莽道无巴鼻，只有吾心孔孟师。"]},{"t":"黄山","f":"七言律诗","c":["几度黄山见客谈，黄山此日果无惭。","春藏太古三千洞，天与游人五百岩。","每觉晚晴犹壑雨，才言好处辄僧庵。","千年岂敢论谁到，老子题诗满石岚。"]},{"t":"黄山道中和光岳","f":"七言律诗","c":["拄杖閒随自在行，八年今又共徐生。","扶持一老閒寻乐，起动诸峰出远迎。","每处诗还游寺好，老人眼却看山明。","我曹分定该云水，每谓苍天赋极平。"]},{"t":"登鸡笼寺","f":"七言律诗","c":["一蹬盘空一蹬回，白云苍树打成堆。","题诗朗月清风到，招手千峰万壑来。","今古此峰天栋柱，烟云何处佛楼台。","我来不肯题名姓，莫笑尧夫是打乖。"]},{"t":"与东川雪潭诸友游定山真珠泉","f":"七言律诗","c":["黄山地主老詹随，此地如今地主谁。","诸子欲寻深处去，源头先却老夫知。","短藜水石閒须可，老笔风花醉颇宜。","某树某丘真了了，归来明日点新诗。"]},{"t":"登西峰和光岳韵","f":"七言律诗","c":["定山峰下小西峰，此日相携又一筇。","稍稍烟霞聊傍我，匆匆云水莫劳公。","赘疣水假閒文字，髣髴儿曹祇父风。","总愧明朝东海袖，鳌峰夭姥正芙蓉。"]},{"t":"定山和东川","f":"七言律诗","c":["悠然万古一同观，眼底天机果万端。","天地风光休少避，老夫酒量颇能宽。","偶曾帝伯皇王熟，肯放风花雪月漫。","周邵后人如论我，尧夫脚下任谁安。"]},{"t":"鸢飞鱼跃亭晚坐和光岳","f":"七言律诗","c":["领略无弦太古风，孤亭小坐意何穷。","自知鱼跃鸢飞妙，都在云閒水淡中。","玄默不言天本静，清光无我月能公。","细看太极当年说，老子而今意偶同。"]},{"t":"和东川定山庄","f":"七言律诗","c":["白云多谢此山灵，识得先生杖履情。","巨梃每劳相见扣，洪钟非是敢无鸣。","客留知己贫何厌，屋傍秋山破也清。","自枉群仙长过我，我家何敢冒蓬瀛。"]},{"t":"泛霁月溪用韵","f":"七言律诗","c":["一曲川云一酒壶，武夷谁道定山无。","杖藜偶自随花柳，老子分明在画图。","满眼风光刚活动，百年老脚正糊涂。","不知往日朱元晦，云水风流有是乎。"]},{"t":"曹城和东川","f":"七言律诗","c":["云水苍天已付公，百年游走意何穷。","好山到处虽真好，风漠如今却更风。","到底此身閒自乐，与人佳兴老真同。","白头明日閒衣钵，肯负徐家二阮东。"]},{"t":"仙踪和光岳","f":"七言律诗","c":["大帽宽衫晚袖谁，远峰羸马欲何追。","风光醉属先生管，山水生来地主随。","到处放怀皆可乐，老来得手莫言迟。","山人只爱山中走，如此行藏断不疑。"]},{"t":"溪山和东川","f":"七言律诗","c":["醉点溪花看水流，白云留我此溪头。","不知川上无穷意，数到濂溪是几秋。","老兴正狂花亦舞，天几如此鸟频讴。","钓台正在无人处，天送先生到此游。"]},{"t":"作春风亭以处光岳","f":"七言律诗","c":["春风谁遣月溪浔，我屋居然又我岑。","岂有一人如子到，可无半榻此云深。","眼中豪杰谁徐孺，天下人家几卧林。","每夜小趺明月坐，传衣或此是传心。"]},{"t":"作东风亭和东川","f":"七言律诗","c":["小亭活水涧之阿，占我溪山景亦多。","何处偶看春暖日，我家须办子行窝。","卑微幸托高眠久，褊窄其如大舞何。","强说春风真错许，软夫正有一团和。"]},{"t":"溪上与东川雪潭石泉橘潭诸友钓饮","f":"七言律诗","c":["九曲风光主客分，一人一曲弄溪云。","浴沂每自论前古，此日相看似昔闻。","饮量且须容病叟，老狂何敢让诸君。","醉扶童子归来晚，花柳前川漾夕曛。"]},{"t":"川上和光岳","f":"七言律诗","c":["潦倒前川鼓枻歌，浮云流水岂胜过。","也知圣世千年里，未始羊裘一个多。","酒盏漫倾刚月上，钓丝才飏恰风和。","谁将出处閒相比，我与严陵竟若何。"]},{"t":"和光岳津字","f":"七言律诗","c":["何许乾坤活水滨，风光邀得酒杯频。","果谁风月无边处，坐我神仙四五人。","醉里此天真一幕，眼中万物总吾春。","烟霞万古天教管，莫笑先生不要津。"]},{"t":"和光岳再游霁月溪","f":"七言律诗","c":["风光诸子屡相携，又泛吾家霁月溪。","已醉酒还能大酌，漫游诗不厌重题。","我惟活水聊江北，客有佳人是会稽。","万古乾坤无彼此，眼中观物莫相迷。"]},{"t":"和光岳","f":"七言律诗","c":["草庭凉露未眠时，歌尽刘因一卷诗。","何处客同玄酒坐，三更月在碧梧枝。","花兼醉影閒相舞，蛙有天机自不知。","欲把朱弦弹一曲，白云随处有钟期。"]},{"t":"和光岳","f":"七言律诗","c":["人间万事本难羁，酒盏花枝未许辞。","山水自该吾辈管，庙堂焉用野人为。","身于静处真能乐，意到悠然勿有诗。","今夜老怀当不浅，青天明月莫来迟。"]},{"t":"题雪潭","f":"七言律诗","c":["川上何来偶坐时，天机之妙乃如斯。","乾坤此脉那能断，今古何人更许知。","五六辈中吾与点，三千年后我还谁。","平湖邀我南川老，许到鳌峰和此诗。"]},{"t":"送东川雪潭至摩尼峰","f":"七言律诗","c":["懒散乾坤信步行，棕鞋布袜颇能轻。","偶从老树孤云顶，又尽南风半日情。","何地暑堪留酷吏，此凉天乃赠先生。","尧夫十二行窝处，此是行窝第一清。"]},{"t":"送东川雪潭至真州有作","f":"七言律诗","c":["白头挥汗未能乾，五月真州在马鞍。","盛暑为谁曾远出，病躯今日可容难。","江山几处真风月，今古何人此肺肝。","明日短筇谁傍我，祇应清梦绕渔竿。"]},{"t":"和韵赠东川别东川至先与余游黄山","f":"七言律诗","c":["白帽何来坐我斋，衣裳片片是云裁。","便同云水千峰去，也做神仙两月来。","世路可终无活水，乡山元旧傍天台。","相逢眉宇居然别，莫怪山中伴侣猜。"]},{"t":"与王汝昌魏仲瞻雨夜小酌","f":"七言律诗","c":["我家玄酒无人共，忽此陶然弄瓦壶。","赠我一杯陶靖节，荅君几首邵尧夫。","草堂今夜能来几，我辈人间此会无。","醉倒莫孤江上月，明朝空伴钓渔徒。"]},{"t":"送吉水张兼岳宿守兼素弟一峰先生戚也","f":"七言律诗","c":["西山眉宇阁清秋，何处骑驴自宿州。","小榻一年三敝馆，青灯十语九金牛。","老怀天下惟张觷，吾弟苏家又子由。","何日湖西寻宿草，吞声同上水心楼。"]},{"t":"上元道中有作明道先生曾为上元主簿","f":"七言律诗","c":["茂叔江亭草一窗，四时佳趣果能降。","川云浩荡真如我，花柳青红又过江。","明道先生能有几，上元风物本难双。","天游偶到忘言处，一笑乾坤正满腔。"]},{"t":"游茅山","f":"七言律诗","c":["莽莽空尘漫几毫，天风鹏辈岂知劳。","山教太极圈中阔，天放先生帽顶高。","万里风光全倜傥，百年人物且英豪。","茅家兄弟谁相报，说我箕山太古樵。"]},{"t":"秦用中过江贽以诗奉答","f":"七言律诗","c":["东南正气撑天地，此卷凭谁更一携。","吾子不愁无杜甫，老夫今岂是须溪。","长江直与青天北，老凤孤鸣越水西。","每笑低头拜东野，白头今更不胜低。"]},{"t":"出港","f":"七言律诗","c":["老子江南自在行，无端诗思绕湖生。","舟从小港摇初出，天与青山看半晴。","醒里风花元脱洒，眼中鱼鸟自分明。","化工多少悠然趣，纵有王维画不成。"]},{"t":"中村书屋为贵溪叶以贞赋","f":"七言律诗","c":["谁将万卷老颜回，碎屋三间紫翠隈。","万古不花文字眼，先生元是活书堆。","自家朗月天无限，到处浮云水一杯。","打得人间糟粕透，庖羲画画是秦灰。"]},{"t":"清溪","f":"七言律诗","c":["清溪绿树绕东西，处处逢诗不敢题。","无赖雨能连甲子，最佳山直到苕溪。","江湖有债閒游老，世事无能白首低。","肯为思家长再拜，孤舟半夜子规啼。"]},{"t":"送张博秀才还永丰博求一峰墓铭","f":"七言律诗","c":["不见人龙盖世英，眼中今是老门生。","百年朋友斯文泪，万古师徒骨肉情。","此老平生真不忝，何人死后敢辞铭。","栖云有石撑天地，先请君磨万丈平。"]},{"t":"承宿州守张兼素不远数百里过访坐我草亭数日于其别也诗以送之 其一","f":"七言律诗","c":["明日江沙到晚秋，见君还似见金牛。","孤灯小榻聊三宿，白日青天又九州。","今古有怀停酒盏，乾坤无语坐江楼。","明良又是君臣会，凤鸟河图莫浪愁。"]},{"t":"承宿州守张兼素不远数百里过访坐我草亭数日于其别也诗以送之 其二","f":"七言律诗","c":["叉手东风紫水涯，独将双耳洗黄埃。","山中白酒偶然熟，此老青天何处来。","浮世百年教我坐，老怀今日见君开。","明朝匹马休回首，自古云台即钓台。"]},{"t":"送张兼素至东葛","f":"七言律诗","c":["君乘舴艋来何处，贱子骑驴是送谁。","二老白头今酒夜，万峰明月此楼诗。","留连别馆非无谓，去住青天想自知。","我正桐江扶汉鼎，先生行矣莫多疑。"]},{"t":"游香泉陪兼素","f":"七言律诗","c":["南川老子乌江别，留鹤先生龙洞回。","此地天留吾友到，中秋月与老夫陪。","神游一路逍遥国，诗在千峰紫翠堆。","如此风光如此辈，百年何苦不三杯。"]},{"t":"重过庄严寺观大树","f":"七言律诗","c":["定山居士老騃痴，又作庄严大树诗。","老去万无元宿在，种时多只此山知。","不分孔墨依身世，无补兴亡过汉隋。","斤斧欲寻吾手病，力扶名教古人谁。"]},{"t":"送司寇张先生 其一","f":"七言律诗","c":["一元自古君臣会，又见明良到圣朝。","恭已无为真帝舜，我公今日自皋陶。","忧勤社稷头颅白，斟酌乾坤斗柄高。","天下得人吾所愿，敢将圣德颂唐尧。"]},{"t":"送司寇张先生 其二","f":"七言律诗","c":["闻在朝廷荐士公，卑人何敢列豪雄。","公门固是人才薮，野物何堪药笼中。","病使逍遥扶白日，老将行止托苍穹。","铨曹果说吾堪用，请选沧江作钓翁。"]},{"t":"贺怀玉先生定山枉顾","f":"七言律诗","c":["蓬莱人每到蓬莱，此老真堪此地来。","眼底风光拈笔有，空中楼阁放天开。","敢拚千古留公醉，却有双泉是我醅。","何处江门閒老子，题诗到此亦忘回。"]},{"t":"挽任员外父母","f":"七言律诗","c":["何处伤心写肺肝，桂林无树不秋丹。","凝之墓木今虽拱，原父文章汉亦难。","万事天容儿子定，平生人打墓碑看。","百年父母终谁在，老子题诗泪不乾。"]},{"t":"施公节枉顾","f":"七言律诗","c":["水华云石尽溪涯，何许柴门到子开。","笑肯青山甘我共，远携书卷过江来。","一瓢天与斟风月，半榻吾宁惜钓台。","别去明朝须费眼，洞门留取认天台。"]},{"t":"寄题六江桥","f":"七言律诗","c":["礼乐乾坤已备任，江山底处许孤襟。","六江老眼吾真到，惠爱何人此最深。","欲济无梁须尔是，买田为井亦如今。","深山惟有区区在，得尽裁成万古心。"]},{"t":"和吕大仆见寄","f":"七言律诗","c":["一瓢偷枕华山春，閒与希夷作后尘。","老懒自惟甘水石，不才何敢废君臣。","许知天地行藏了，肯恼江云奉荅频。","但恐终南终捷径，白云他负眼中人。"]}]};